// Implemented the Gemini service for question, study guide, and speech generation.
import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Question, Difficulty, QuestionCategory, StudyGuideLength } from '../types';

// Per guidelines, create a new GoogleGenAI instance for each call to ensure the latest API key is used.
const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY! });

// Helper functions for audio decoding as per guidelines
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

// Schema for the question generation to ensure structured output
const questionSchema = {
  type: Type.OBJECT,
  properties: {
    question: { type: Type.STRING, description: 'The question text.' },
    options: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: 'An array of 4 multiple-choice options.'
    },
    answer: { type: Type.STRING, description: 'The correct option from the options array.' },
    explanation: { type: Type.STRING, description: 'A detailed explanation for why the answer is correct.' },
    category: {
      type: Type.STRING,
      description: 'The category of the question.',
      enum: ['Prepare the data', 'Model the data', 'Visualize and analyze the data', 'Deploy and maintain assets']
    },
    difficulty: {
      type: Type.STRING,
      description: 'The difficulty of the question.',
      enum: ['Easy', 'Medium', 'Hard']
    }
  },
  required: ['question', 'options', 'answer', 'explanation', 'category', 'difficulty']
};

export const generateQuestion = async (difficulty: Difficulty, category: QuestionCategory | 'All' = 'All'): Promise<Question> => {
    // Per guidelines, use gemini-3-pro-preview for complex text tasks
    const model = 'gemini-3-pro-preview';

    let categoryPromptSection = `
    The question must be relevant to one of the four main skill areas:
    1. Prepare the data
    2. Model the data
    3. Visualize and analyze the data
    4. Deploy and maintain assets`;

    if (category !== 'All') {
        categoryPromptSection = `The question must be relevant to the skill area: "${category}".`;
    }

    const prompt = `Generate a unique, high-quality, multiple-choice question for the Microsoft Power BI PL-300 certification exam.

    ${categoryPromptSection}

    The desired difficulty for this question is: ${difficulty === 'Adaptive' ? 'varied' : difficulty}.

    The question should be practical and scenario-based. Provide exactly 4 distinct options. Ensure only one option is correct.
    Provide a clear and concise explanation for the correct answer.

    Return the output in the specified JSON format.`;

    const schemaForRequest = JSON.parse(JSON.stringify(questionSchema));
    if (category !== 'All') {
        schemaForRequest.properties.category.enum = [category];
    }

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: schemaForRequest,
                temperature: 0.9,
            },
        });

        const text = response.text;
        const generatedQuestion = JSON.parse(text);

        if (!generatedQuestion.question || !Array.isArray(generatedQuestion.options) || generatedQuestion.options.length !== 4 || !generatedQuestion.answer || !generatedQuestion.explanation || !generatedQuestion.category || !generatedQuestion.difficulty) {
            throw new Error("Received malformed question data from API.");
        }
        if (!generatedQuestion.options.includes(generatedQuestion.answer)) {
             throw new Error("The provided answer is not in the options list.");
        }

        return generatedQuestion as Question;
    } catch (error) {
        console.error("Error generating question:", error);
        throw new Error("Failed to generate a new question. Please try again.");
    }
};

export const generateSpeech = async (text: string, voiceName: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    const ai = getAiClient();
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Say clearly and naturally: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) {
            throw new Error("No audio data received from the API.");
        }

        const decodedAudio = decodeBase64(base64Audio);
        const audioBuffer = await decodeAudioData(
            decodedAudio,
            audioContext,
            24000,
            1
        );
        return audioBuffer;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw error;
    }
};

export const getPersonalizedFeedback = async (question: Question, userAnswer: string): Promise<string> => {
    const model = 'gemini-3-flash-preview';
    const isCorrect = question.answer === userAnswer;

    const prompt = `A student has answered a question about Power BI. Your task is to provide personalized feedback in an encouraging and professional tone.

    Question: "${question.question}"
    Correct Answer: "${question.answer}"
    Student's Answer: "${userAnswer}"

    ${isCorrect 
        ? `The student answered correctly. Start by confirming their answer is correct (e.g., "That's correct!"). Then, briefly reinforce WHY their answer is correct, perhaps adding a small extra tip related to the concept.`
        : `The student's answer was incorrect. Start with an encouraging tone (e.g., "Not quite, but this is a common point of confusion."). Explain why their choice, "${userAnswer}", is incorrect and then clearly explain why "${question.answer}" is the correct choice. Keep it positive and focused on learning.`
    }

    Keep the feedback concise and helpful.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({ model, contents: prompt });
        const feedback = response.text;
        if (!feedback) {
            throw new Error("Received empty feedback from API.");
        }
        return feedback;
    } catch (error) {
        console.error("Error generating feedback:", error);
        throw new Error("Failed to generate personalized feedback.");
    }
};

export const generateStudyGuideStream = async (
    category: QuestionCategory | 'All', 
    length: StudyGuideLength, 
    onChunk: (chunk: string) => void
): Promise<void> => {

    const model = length === 'Concise' ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview';

    let lengthPrompt = '';
    switch(length) {
        case 'Concise':
            lengthPrompt = 'Keep the entire guide concise and under 200 words.';
            break;
        case 'Detailed':
            lengthPrompt = 'The guide should be detailed, around 500-700 words.';
            break;
        case 'Comprehensive':
            lengthPrompt = 'The guide should be very comprehensive, around 1000-1500 words.';
            break;
    }

    let categoryPrompt = '';
    if (category === 'All') {
        categoryPrompt = `The guide must cover all four main skill areas of the exam:
        1. Prepare the data
        2. Model the data
        3. Visualize and analyze the data
        4. Deploy and maintain assets

        For each skill area, provide an overview, detailed bullet points, and practical tips.`;
    } else {
        categoryPrompt = `The guide should focus exclusively on the topic: "${category}".`;
    }

    const prompt = `Create a high-quality study guide for the Microsoft Power BI PL-300 certification exam.

    ${categoryPrompt}

    **Crucially, you must include practical, real-world examples and, where appropriate, mini case studies to illustrate the key concepts.** This is essential for helping the user understand the material in a practical context.

    Use Markdown for formatting. Use headings (#, ##), bolding, and lists to create a clear, readable structure. The tone should be professional, encouraging, and easy to understand.

    ${lengthPrompt}`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContentStream({
            model: model,
            contents: prompt,
            config: {
                temperature: 0.6,
            },
        });

        for await (const chunk of response) {
            const chunkText = chunk.text;
            if (chunkText) {
                onChunk(chunkText);
            }
        }
    } catch (error) {
        console.error("Error generating study guide:", error);
        throw new Error("Failed to generate the study guide. Please try again.");
    }
};

export const generateRelatedTips = async (question: Question): Promise<string[]> => {
    const model = 'gemini-3-flash-preview';
    const tipsSchema = {
        type: Type.OBJECT,
        properties: {
            tips: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
                description: 'An array of 2-3 concise, practical tips related to the question\'s topic.'
            }
        },
        required: ['tips']
    };

    const prompt = `Based on this PL-300 exam question, generate 2-3 additional, concise, and practical tips. The tips should help a student better understand the core concept.

    Question: "${question.question}"
    Topic: "${question.category}"

    Focus on providing actionable advice or highlighting common pitfalls related to the topic.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: tipsSchema,
                temperature: 0.8,
            },
        });

        const text = response.text;
        const result = JSON.parse(text);

        if (!result.tips || !Array.isArray(result.tips)) {
            throw new Error("Received malformed tips data from API.");
        }

        return result.tips as string[];
    } catch (error) {
        console.error("Error generating related tips:", error);
        // Don't throw, return empty array to avoid breaking UI for a non-critical feature
        return []; 
    }
};

export const generatePracticeExamStream = async (onChunk: (chunk: string) => void): Promise<void> => {
    const model = 'gemini-3-pro-preview';

    const prompt = `Generate a full practice exam for the PL-300 Power BI certification. The exam should contain 25 high-quality, scenario-based, multiple-choice questions. 

    Ensure the questions are distributed realistically across the four main skill areas:
    - Prepare the data
    - Model the data
    - Visualize and analyze the data
    - Deploy and maintain assets

    For each question, provide the following in order:
    1. The question number (e.g., "**Question 1:**").
    2. The full question text.
    3. Four options labeled A, B, C, and D.
    4. The correct answer (e.g., "**Correct Answer:** C").
    5. A detailed explanation of why the answer is correct and why the other options are incorrect.

    Format the entire output as a single, well-structured Markdown document. Use headings for a title, and use bolding and lists to ensure the document is clean, professional, and easy to read.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContentStream({
            model: model,
            contents: prompt,
            config: {
                temperature: 0.6,
            },
        });

        for await (const chunk of response) {
            const chunkText = chunk.text;
            if (chunkText) {
                onChunk(chunkText);
            }
        }
    } catch (error) {
        console.error("Error generating practice exam:", error);
        throw new Error("Failed to generate the practice exam. Please try again.");
    }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;
const AVAILABLE_VOICES = ['Zephyr', 'Puck', 'Charon', 'Kore', 'Fenrir'];

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  // Speech states
  const [selectedVoice, setSelectedVoice] = useState('Zephyr');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  // Timer effect
  useEffect(() => {
    if (timer === 0) return;

    if (timeLeft <= 0) {
      finishQuiz();
      return;
    }

    const intervalId = setInterval(() => {
      setTimeLeft(prevTime => prevTime - 1);
    }, 1000);

    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  // Fetch questions effect
  useEffect(() => {
    const loadQuestions = async () => {
      setIsLoading(true);
      setError(null);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) {
          onQuizEnd([], 0);
          return;
        }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          const firstQuestion = await generateQuestion(difficulty, category);
          setQuestions([firstQuestion]);
          setIsLoading(false);
        } catch (err) {
          setError(err instanceof Error ? err.message : 'Failed to load question.');
          setIsLoading(false);
        }
      }
    };
    loadQuestions();
  }, [mode, difficulty, category, bookmarkedQuestions, onQuizEnd]);

  // Audio cleanup on unmount
  useEffect(() => {
    return () => {
      stopSpeaking();
    };
  }, []);

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
      audioSourceRef.current.stop();
      audioSourceRef.current = null;
    }
    setIsSpeaking(false);
  };

  const handleReadAloud = async () => {
    if (isSpeaking) {
      stopSpeaking();
      return;
    }

    if (!currentQuestion) return;

    setIsSpeaking(true);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const textToRead = `${currentQuestion.question}. Options are: ${currentQuestion.options.map((opt, i) => `${String.fromCharCode(65 + i)}: ${opt}`).join(', ')}`;
      const buffer = await generateSpeech(textToRead, selectedVoice, audioContextRef.current);

      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setIsSpeaking(false);

      audioSourceRef.current = source;
      source.start();
    } catch (err) {
      console.error("Speech generation failed", err);
      setIsSpeaking(false);
    }
  };

  const handleAnswerSelect = (option: string) => {
    if (quizState === 'answering') {
      setSelectedAnswer(option);
    }
  };

  const handleSubmit = useCallback(() => {
    if (quizState !== 'answering' || selectedAnswer === null || !currentQuestion) return;

    const isCorrect = selectedAnswer === currentQuestion.answer;
    const newResult: ExamResult = {
      question: currentQuestion,
      userAnswer: selectedAnswer,
      isCorrect,
    };
    setResults(prev => [...prev, newResult]);
    setQuizState('answered');

  }, [quizState, selectedAnswer, currentQuestion]);

  const handleNextQuestion = useCallback(async () => {
    stopSpeaking();
    if (quizState !== 'answered') return;

    const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;

    if (currentQuestionIndex + 1 >= totalQuestionsInSet) {
      finishQuiz();
      return;
    }

    const nextIndex = currentQuestionIndex + 1;
    setSelectedAnswer(null);
    setQuizState('answering');
    setCurrentQuestionIndex(nextIndex);

    if (mode !== 'BookmarkReview' && nextIndex >= questions.length) {
        setIsLoading(true);
        setError(null);
        try {
            const nextQuestion = await generateQuestion(difficulty, category);
            setQuestions(prev => [...prev, nextQuestion]);
        } catch(err) {
            setError(err instanceof Error ? err.message : 'Failed to load next question.');
        } finally {
            setIsLoading(false);
        }
    }
  }, [quizState, currentQuestionIndex, questions.length, mode, bookmarkedQuestions.length, difficulty, category, finishQuiz]);

  const handleSkip = useCallback(() => {
    stopSpeaking();
    if (mode === 'Exam' || quizState !== 'answering' || !currentQuestion) return;

    const skippedResult: ExamResult = {
        question: currentQuestion,
        userAnswer: null,
        isCorrect: false
    };
    setResults(prev => [...prev, skippedResult]);
    setQuizState('answered');
  }, [mode, quizState, currentQuestion]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Enter' && selectedAnswer && quizState === 'answering') {
            handleSubmit();
        } else if (e.key.toLowerCase() === 'n' && quizState === 'answered') {
            handleNextQuestion();
        } else if (e.key.toLowerCase() === 's' && quizState === 'answering' && mode !== 'Exam') {
            handleSkip();
        } else if (e.key.toLowerCase() === 'b' && currentQuestion) {
            onToggleBookmark(currentQuestion);
        } else if (e.key.toLowerCase() === 'v') {
            handleReadAloud();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSubmit, handleNextQuestion, handleSkip, onToggleBookmark, selectedAnswer, quizState, mode, currentQuestion, isSpeaking, selectedVoice]);


  if (isLoading && questions.length === 0) {
    return <Loader text={mode === 'BookmarkReview' ? "Loading bookmarked questions..." : "Generating your first question..."} />;
  }

  if (error) {
    return (
      <div className="text-center p-8 bg-card rounded-lg">
        <h2 className="text-2xl font-bold text-danger mb-4">An Error Occurred</h2>
        <p className="text-slate-300 mb-6">{error}</p>
        <button onClick={() => onQuizEnd([], 0)} className="bg-primary hover:bg-primary-dark text-primary-foreground font-bold py-2 px-4 rounded">
          Back to Dashboard
        </button>
      </div>
    );
  }

  if (!currentQuestion) {
    return <Loader text="Preparing quiz..." />;
  }

  const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
  const progressPercentage = ((currentQuestionIndex + 1) / totalQuestionsInSet) * 100;

  const formatTime = (seconds: number) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getOptionClass = (option: string) => {
    const isSelected = selectedAnswer === option;
    if (quizState === 'answered') {
        const isCorrect = option === currentQuestion.answer;
        if (isCorrect) return 'bg-success/30 border-success text-foreground';
        if (isSelected) return 'bg-danger/30 border-danger text-foreground';
        return 'opacity-50';
    }
    return isSelected
        ? 'bg-primary/30 border-primary text-foreground'
        : 'bg-card hover:bg-border border-border';
  };

  return (
    <div className="max-w-4xl mx-auto animate-fade-in">
        <div className="flex justify-between items-center mb-4">
            <h2 className="text-2xl font-bold">{mode === 'Exam' ? 'Exam Simulation' : 'Practice Session'}</h2>
            {timer > 0 && (
                <div className={`flex items-center gap-2 font-semibold p-2 rounded-lg text-lg ${timeLeft <= 60 ? 'text-danger animate-pulse' : 'text-slate-300'}`}>
                    <StopwatchIcon />
                    <span>{formatTime(timeLeft)}</span>
                </div>
            )}
        </div>

        <div className="w-full bg-border rounded-full h-2.5 mb-6">
            <div className="bg-primary h-2.5 rounded-full" style={{ width: `${progressPercentage}%`, transition: 'width 0.3s' }}></div>
        </div>

        <div className="bg-card p-6 sm:p-8 rounded-lg shadow-lg border border-border">
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-4">
                    <p className="text-sm font-semibold text-slate-400">Question {currentQuestionIndex + 1} of {totalQuestionsInSet}</p>

                    {/* Voice Controls */}
                    <div className="flex items-center gap-2 bg-background/30 px-2 py-1 rounded-md border border-border/50">
                        <select 
                          value={selectedVoice} 
                          onChange={(e) => setSelectedVoice(e.target.value)}
                          className="text-xs bg-transparent border-none focus:ring-0 text-slate-300 cursor-pointer"
                          disabled={isSpeaking}
                        >
                            {AVAILABLE_VOICES.map(v => <option key={v} value={v}>{v}</option>)}
                        </select>
                        <button
                          onClick={handleReadAloud}
                          className={`p-1 rounded-md transition-colors ${isSpeaking ? 'bg-danger text-white' : 'hover:bg-primary/20 text-primary-light'}`}
                          title={isSpeaking ? "Stop" : "Read Aloud"}
                        >
                            {isSpeaking ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                        </button>
                    </div>
                </div>

                <button
                    onClick={() => onToggleBookmark(currentQuestion)}
                    className={`transition-colors ${isBookmarked(currentQuestion) ? 'text-yellow-400' : 'text-slate-500 hover:text-yellow-300'}`}
                    aria-label={isBookmarked(currentQuestion) ? 'Remove bookmark' : 'Add bookmark'}
                >
                    <BookmarkIcon filled={isBookmarked(currentQuestion)} />
                </button>
            </div>

            <h3 className="text-xl md:text-2xl font-semibold mb-6 text-slate-200">{currentQuestion.question}</h3>

            <div className="space-y-3">
                {currentQuestion.options.map((option, index) => (
                    <button
                        key={index}
                        onClick={() => handleAnswerSelect(option)}
                        disabled={quizState === 'answered'}
                        className={`w-full text-left p-4 rounded-lg border-2 transition-all text-base md:text-lg ${getOptionClass(option)}`}
                    >
                        <span className="font-mono mr-3">{String.fromCharCode(65 + index)}.</span>
                        {option}
                    </button>
                ))}
            </div>

            {quizState === 'answered' && (
                <div className="mt-6">
                    <DexterExplains question={currentQuestion} userAnswer={results[results.length - 1]?.userAnswer} />
                </div>
            )}

            <div className="mt-8 flex flex-col sm:flex-row gap-4">
                {quizState === 'answering' ? (
                    <>
                        {mode !== 'Exam' && (
                            <button onClick={handleSkip} className="flex-1 order-2 sm:order-1 bg-slate-600 hover:bg-slate-700 text-white font-bold py-3 px-4 rounded-lg text-lg">
                                Skip
                            </button>
                        )}
                        <button
                            onClick={handleSubmit}
                            disabled={!selectedAnswer}
                            className="flex-1 order-1 sm:order-2 bg-primary hover:bg-primary/90 text-primary-foreground font-bold py-3 px-4 rounded-lg text-lg disabled:bg-slate-500 disabled:cursor-not-allowed"
                        >
                            Submit
                        </button>
                    </>
                ) : (
                    <button
                        onClick={handleNextQuestion}
                        className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-bold py-3 px-4 rounded-lg text-lg"
                    >
                        {currentQuestionIndex + 1 === totalQuestionsInSet ? 'Finish & View Results' : 'Next Question'}
                    </button>
                )}
            </div>
             {isLoading && currentQuestionIndex >= questions.length - 1 && <Loader text="Generating next question..." />}
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

import React from 'react';

export const SpeakerIcon: React.FC<{ className?: string }> = ({ className = "w-6 h-6" }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    className={className}
    fill="none" 
    viewBox="0 0 24 24" 
    stroke="currentColor" 
    strokeWidth={2}
  >
    <path 
        strokeLinecap="round" 
        strokeLinejoin="round" 
