// Implemented the main App component to handle state management, view routing, data persistence, and API key selection.
import React, { useState, useEffect, useCallback } from 'react';
import { Dashboard } from './components/Dashboard';
import { Quiz } from './components/Quiz';
import { SessionReview } from './components/SessionReview';
import { BookmarkedQuestions } from './components/BookmarkedQuestions';
import { ApiKeySelector } from './components/ApiKeySelector';
import type { ProgressData, Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from './types';
import { PowerBiIcon } from './components/icons/PowerBiIcon';
import { PerformanceSummaryModal } from './components/PerformanceSummaryModal';
import { ThemeToggle } from './components/ThemeToggle';
import { PracticeExamDownloader } from './components/PracticeExamDownloader';

type View = 'dashboard' | 'quiz' | 'review' | 'bookmarks';
type Theme = 'light' | 'dark';

const INITIAL_PROGRESS: ProgressData = {
  totalQuestions: 0,
  totalCorrect: 0,
  currentStreak: 0,
  categoryStats: {
    'Prepare the data': { correct: 0, total: 0 },
    'Model the data': { correct: 0, total: 0 },
    'Visualize and analyze the data': { correct: 0, total: 0 },
    'Deploy and maintain assets': { correct: 0, total: 0 },
  },
  bookmarkedQuestions: [],
  accuracyHistory: [],
  examHistory: [],
};

const APP_DATA_KEY = 'pl300-progress';

interface SessionSummary {
    score: number;
    total: number;
    accuracy: string;
    timeTaken: number;
}

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);
  const [progressData, setProgressData] = useState<ProgressData>(INITIAL_PROGRESS);
  const [quizSettings, setQuizSettings] = useState<{ difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }>({
    difficulty: 'Adaptive',
    timer: 15,
    mode: 'Practice',
    category: 'All',
  });
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [showSummaryModal, setShowSummaryModal] = useState(false);
  const [sessionSummary, setSessionSummary] = useState<SessionSummary | null>(null);
  const [theme, setTheme] = useState<Theme>('dark');
  const [showPracticeExamModal, setShowPracticeExamModal] = useState(false);

  // Check for API key on load
  useEffect(() => {
    const checkApiKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      } else {
        // If not in AI Studio environment, assume key is provided via process.env
        setHasApiKey(true);
      }
    };
    checkApiKey();
  }, []);

  // Effect to load theme on initial load
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as Theme | null;
    const initialTheme = savedTheme || 'dark';
    setTheme(initialTheme);
  }, []);

  // Effect to apply theme class and save to localStorage
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  // Effect to load data on initial load
  useEffect(() => {
    try {
      const savedData = localStorage.getItem(APP_DATA_KEY);
      if (savedData) {
        const parsedData = JSON.parse(savedData);
        const mergedData: ProgressData = {
          ...INITIAL_PROGRESS,
          ...parsedData,
          categoryStats: { ...INITIAL_PROGRESS.categoryStats, ...(parsedData.categoryStats || {}), },
          bookmarkedQuestions: parsedData.bookmarkedQuestions || [],
          accuracyHistory: parsedData.accuracyHistory || [],
          examHistory: parsedData.examHistory || [],
        };
        setProgressData(mergedData);
      } else {
        setProgressData(INITIAL_PROGRESS);
      }
    } catch (error) {
      console.error("Failed to load progress data. Resetting.", error);
      setProgressData(INITIAL_PROGRESS);
    }
  }, []);

  // Effect to save data whenever it changes
  useEffect(() => {
    try {
      localStorage.setItem(APP_DATA_KEY, JSON.stringify(progressData));
    } catch (error) {
      console.error("Failed to save progress data", error);
    }
  }, [progressData]);

  const handleStartQuiz = useCallback((settings: { difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }) => {
    setQuizSettings(settings);
    setView('quiz');
  }, []);

  const handleQuizEnd = useCallback((results: ExamResult[], timeTaken: number) => {
    setExamResults(results);

    if (results.length === 0) {
        setView('review');
        return;
    }

    setProgressData(prevData => {
      const newData = { ...prevData, categoryStats: JSON.parse(JSON.stringify(prevData.categoryStats)), accuracyHistory: [...(prevData.accuracyHistory || [])], };
      let newStreak = prevData.currentStreak;
      let sessionCorrect = 0;

      results.forEach(result => {
        newData.totalQuestions += 1;
        const category = result.question.category;
        if (!newData.categoryStats[category]) {
           newData.categoryStats[category] = { correct: 0, total: 0 };
        }
        newData.categoryStats[category].total += 1;

        if (result.isCorrect) {
          newData.totalCorrect += 1;
          newData.categoryStats[category].correct += 1;
          newStreak += 1;
          sessionCorrect += 1;
        } else {
          newStreak = 0;
        }
      });
      newData.currentStreak = newStreak;

      const sessionAccuracy = (sessionCorrect / results.length) * 100;
      newData.accuracyHistory.push({
          session: newData.accuracyHistory.length + 1,
          accuracy: sessionAccuracy,
      });

      const newHistory = [...(prevData.examHistory || []), results].slice(-10);
      newData.examHistory = newHistory;

      return newData;
    });

    const score = results.filter(r => r.isCorrect).length;
    const total = results.length;
    const accuracy = total > 0 ? ((score / total) * 100).toFixed(0) : '0';

    setSessionSummary({ score, total, accuracy, timeTaken });
    setShowSummaryModal(true);
  }, []);

  const handleCloseSummaryModal = useCallback(() => {
    setShowSummaryModal(false);
    setView('review');
  }, []);

  const handleToggleBookmark = useCallback((question: Question) => {
    setProgressData(prevData => {
      const isBookmarked = prevData.bookmarkedQuestions.some(bq => bq.question === question.question);
      return {
        ...prevData,
        bookmarkedQuestions: isBookmarked
          ? prevData.bookmarkedQuestions.filter(bq => bq.question !== question.question)
          : [...prevData.bookmarkedQuestions, question],
      };
    });
  }, []);

  const isBookmarked = useCallback((question: Question) => progressData.bookmarkedQuestions.some(bq => bq.question === question.question), [progressData.bookmarkedQuestions]);
  const handleViewBookmarks = useCallback(() => setView('bookmarks'), []);
  const handleStartBookmarkReview = useCallback(() => handleStartQuiz({ difficulty: 'Easy', timer: 0, mode: 'BookmarkReview', category: 'All' }), [handleStartQuiz]);
  const handleBackToDashboard = useCallback(() => { setExamResults([]); setSessionSummary(null); setView('dashboard'); }, []);
  const handleResetProgress = useCallback(() => {
    if (window.confirm("Are you sure you want to reset all your progress? This action cannot be undone.")) {
        setProgressData(INITIAL_PROGRESS);
        setView('dashboard');
    }
  }, []);

  if (hasApiKey === false) {
    return <ApiKeySelector onKeySelected={() => setHasApiKey(true)} />;
  }

  const renderAppContent = () => {
    switch (view) {
      case 'quiz':
        return <Quiz {...quizSettings} bookmarkedQuestions={progressData.bookmarkedQuestions} onQuizEnd={handleQuizEnd} onToggleBookmark={handleToggleBookmark} isBookmarked={isBookmarked} />;
      case 'review':
        return <SessionReview results={examResults} onBackToDashboard={handleBackToDashboard} theme={theme} />;
      case 'bookmarks':
        return <BookmarkedQuestions questions={progressData.bookmarkedQuestions} onToggleBookmark={handleToggleBookmark} onBackToDashboard={handleBackToDashboard} onStartQuiz={handleStartBookmarkReview} />;
      case 'dashboard':
      default:
        return <Dashboard 
                    progressData={progressData} 
                    onStartQuiz={handleStartQuiz} 
                    onViewBookmarks={handleViewBookmarks} 
                    onResetProgress={handleResetProgress} 
                    onDownloadPracticeExam={() => setShowPracticeExamModal(true)}
                    theme={theme} />;
    }
  };

  return (
    <div className="bg-background text-foreground min-h-screen font-sans">
      <header className="py-4 border-b border-border">
        <div className="max-w-screen-2xl mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <PowerBiIcon className="w-10 h-10" />
            <h1 className="text-2xl md:text-3xl font-bold tracking-tight">PL-300 Power Practice</h1>
          </div>
          <ThemeToggle theme={theme} toggleTheme={toggleTheme} />
        </div>
      </header>
      <main className="max-w-screen-2xl mx-auto p-4 md:p-8">
        {renderAppContent()}
      </main>
       {showSummaryModal && sessionSummary && (
            <PerformanceSummaryModal summary={sessionSummary} onClose={handleCloseSummaryModal} />
        )}
        {showPracticeExamModal && (
            <PracticeExamDownloader onClose={() => setShowPracticeExamModal(false)} />
        )}
      <footer className="text-center py-4 text-slate-500 dark:text-slate-400 text-sm border-t border-border mt-8">
        <p>Powered by Gemini & AI Studio. Built for learning.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;
const AVAILABLE_VOICES = ['Zephyr', 'Puck', 'Charon', 'Kore', 'Fenrir'];

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  // Speech states
  const [selectedVoice, setSelectedVoice] = useState('Zephyr');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  // Timer effect
  useEffect(() => {
    if (timer === 0) return;

    if (timeLeft <= 0) {
      finishQuiz();
      return;
    }

    const intervalId = setInterval(() => {
      setTimeLeft(prevTime => prevTime - 1);
    }, 1000);

    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  // Fetch questions effect
  useEffect(() => {
    const loadQuestions = async () => {
      setIsLoading(true);
      setError(null);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) {
          onQuizEnd([], 0);
          return;
        }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          const firstQuestion = await generateQuestion(difficulty, category);
          setQuestions([firstQuestion]);
          setIsLoading(false);
        } catch (err) {
          setError(err instanceof Error ? err.message : 'Failed to load question.');
          setIsLoading(false);
        }
      }
    };
    loadQuestions();
  }, [mode, difficulty, category, bookmarkedQuestions, onQuizEnd]);

  // Audio cleanup on unmount
  useEffect(() => {
    return () => {
      stopSpeaking();
    };
  }, []);

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
      try {
        audioSourceRef.current.stop();
      } catch (e) {
        // Already stopped
      }
      audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const handleReadAloud = async () => {
    if (isSpeaking || isGeneratingAudio) {
      stopSpeaking();
      return;
    }

    if (!currentQuestion) return;

    setIsGeneratingAudio(true);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const optionsText = currentQuestion.options
        .map((opt, i) => `Option ${String.fromCharCode(65 + i)}: ${opt}`)
        .join('. ');

      const textToRead = `${currentQuestion.question}. ... The options are: ${optionsText}`;

      const buffer = await generateSpeech(textToRead, selectedVoice, audioContextRef.current);

      setIsGeneratingAudio(false);
      setIsSpeaking(true);

      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setIsSpeaking(false);

      audioSourceRef.current = source;
      source.start();
    } catch (err) {
      console.error("Speech generation failed", err);
      setIsGeneratingAudio(false);
      setIsSpeaking(false);
    }
  };

  const handleAnswerSelect = (option: string) => {
    if (quizState === 'answering') {
      setSelectedAnswer(option);
    }
  };

  const handleSubmit = useCallback(() => {
    if (quizState !== 'answering' || selectedAnswer === null || !currentQuestion) return;

    const isCorrect = selectedAnswer === currentQuestion.answer;
    const newResult: ExamResult = {
      question: currentQuestion,
      userAnswer: selectedAnswer,
      isCorrect,
    };
    setResults(prev => [...prev, newResult]);
    setQuizState('answered');

  }, [quizState, selectedAnswer, currentQuestion]);

  const handleNextQuestion = useCallback(async () => {
    stopSpeaking();
    if (quizState !== 'answered') return;

    const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;

    if (currentQuestionIndex + 1 >= totalQuestionsInSet) {
      finishQuiz();
      return;
    }

    const nextIndex = currentQuestionIndex + 1;
    setSelectedAnswer(null);
    setQuizState('answering');
    setCurrentQuestionIndex(nextIndex);

    if (mode !== 'BookmarkReview' && nextIndex >= questions.length) {
        setIsLoading(true);
        setError(null);
        try {
            const nextQuestion = await generateQuestion(difficulty, category);
            setQuestions(prev => [...prev, nextQuestion]);
        } catch(err) {
            setError(err instanceof Error ? err.message : 'Failed to load next question.');
        } finally {
            setIsLoading(false);
        }
    }
  }, [quizState, currentQuestionIndex, questions.length, mode, bookmarkedQuestions.length, difficulty, category, finishQuiz]);

  const handleSkip = useCallback(() => {
    stopSpeaking();
    if (mode === 'Exam' || quizState !== 'answering' || !currentQuestion) return;

    const skippedResult: ExamResult = {
        question: currentQuestion,
        userAnswer: null,
        isCorrect: false
    };
    setResults(prev => [...prev, skippedResult]);
    setQuizState('answered');
  }, [mode, quizState, currentQuestion]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Enter' && selectedAnswer && quizState === 'answering') {
            handleSubmit();
        } else if (e.key.toLowerCase() === 'n' && quizState === 'answered') {
            handleNextQuestion();
        } else if (e.key.toLowerCase() === 's' && quizState === 'answering' && mode !== 'Exam') {
            handleSkip();
        } else if (e.key.toLowerCase() === 'b' && currentQuestion) {
            onToggleBookmark(currentQuestion);
        } else if (e.key.toLowerCase() === 'v') {
            handleReadAloud();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSubmit, handleNextQuestion, handleSkip, onToggleBookmark, selectedAnswer, quizState, mode, currentQuestion, isSpeaking, isGeneratingAudio, selectedVoice]);


  if (isLoading && questions.length === 0) {
    return <Loader text={mode === 'BookmarkReview' ? "Loading bookmarked questions..." : "Generating your first question..."} />;
  }

  if (error) {
    return (
      <div className="text-center p-8 bg-card rounded-lg border border-border">
        <h2 className="text-2xl font-bold text-danger mb-4">An Error Occurred</h2>
        <p className="text-slate-300 mb-6">{error}</p>
        <button onClick={() => onQuizEnd([], 0)} className="bg-primary hover:bg-primary/90 text-primary-foreground font-bold py-2 px-6 rounded-lg transition-colors">
          Back to Dashboard
        </button>
      </div>
    );
  }

  if (!currentQuestion) {
    return <Loader text="Preparing quiz..." />;
  }

  const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
  const progressPercentage = ((currentQuestionIndex + 1) / totalQuestionsInSet) * 100;

  const formatTime = (seconds: number) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getOptionClass = (option: string) => {
    const isSelected = selectedAnswer === option;
    if (quizState === 'answered') {
        const isCorrect = option === currentQuestion.answer;
        if (isCorrect) return 'bg-success/30 border-success text-foreground';
        if (isSelected) return 'bg-danger/30 border-danger text-foreground';
        return 'opacity-50 grayscale-[0.5]';
    }
    return isSelected
        ? 'bg-primary/20 border-primary ring-1 ring-primary text-foreground'
        : 'bg-card hover:bg-border border-border text-slate-300';
  };

  return (
    <div className="max-w-4xl mx-auto animate-fade-in px-2 sm:px-0">
        <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
            <h2 className="text-2xl font-bold tracking-tight">{mode === 'Exam' ? 'Exam Simulation' : mode === 'BookmarkReview' ? 'Bookmark Review' : 'Practice Session'}</h2>
            {timer > 0 && (
                <div className={`flex items-center gap-3 font-mono font-bold px-4 py-2 rounded-full border border-border shadow-inner ${timeLeft <= 60 ? 'text-danger bg-danger/10 animate-pulse' : 'text-slate-400 bg-card'}`}>
                    <StopwatchIcon className="w-5 h-5" />
                    <span className="text-xl">{formatTime(timeLeft)}</span>
                </div>
            )}
        </div>

        <div className="w-full bg-border rounded-full h-2 mb-8 shadow-inner overflow-hidden">
            <div className="bg-primary h-full rounded-full transition-all duration-500 ease-out shadow-[0_0_10px_rgba(99,102,241,0.5)]" style={{ width: `${progressPercentage}%` }}></div>
        </div>

        <div className="bg-card p-6 sm:p-10 rounded-2xl shadow-xl border border-border relative">
            <div className="flex justify-between items-center mb-8">
                <div className="flex flex-wrap items-center gap-3">
                    <span className="bg-primary/10 text-primary-light text-xs font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-primary/20">
                        Question {currentQuestionIndex + 1} of {totalQuestionsInSet}
                    </span>

                    {/* Enhanced Voice Controls */}
                    <div className="flex items-center gap-1 bg-background/50 p-1 rounded-lg border border-border group">
                        <div className="relative">
                            <select 
                              value={selectedVoice} 
                              onChange={(e) => setSelectedVoice(e.target.value)}
                              className="text-xs bg-transparent border-none focus:ring-0 text-slate-400 cursor-pointer pr-6 py-1 font-medium hover:text-slate-200 transition-colors appearance-none"
                              disabled={isSpeaking || isGeneratingAudio}
                              title="Select Voice"
                            >
                                {AVAILABLE_VOICES.map(v => <option key={v} value={v} className="bg-card text-foreground">{v}</option>)}
                            </select>
                            <div className="absolute inset-y-0 right-1 flex items-center pointer-events-none text-slate-500">
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </div>
                        </div>
                        <button
                          onClick={handleReadAloud}
                          className={`p-1.5 rounded-md transition-all ${
                            isSpeaking ? 'bg-danger text-white scale-110' : 
                            isGeneratingAudio ? 'bg-primary/50 text-white animate-pulse' :
                            'hover:bg-primary/20 text-primary-light'
                          }`}
                          title={isSpeaking ? "Stop" : isGeneratingAudio ? "Generating..." : "Read Aloud (V)"}
                        >
                            {isGeneratingAudio ? (
                                <svg className="w-4 h-4 animate-spin" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                            ) : isSpeaking ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                        </button>
                    </div>

                    {isSpeaking && (
                        <div className="flex gap-0.5 items-end h-3 px-1">
                            <div className="w-1 bg-primary-light rounded-full animate-[bounce_0.6s_infinite_0s] h-1.5"></div>
                            <div className="w-1 bg-primary-light rounded-full animate-[bounce_0.6s_infinite_0.1s] h-3"></div>
                            <div className="w-1 bg-primary-light rounded-full animate-[bounce_0.6s_infinite_0.2s] h-2"></div>
                            <div className="w-1 bg-primary-light rounded-full animate-[bounce_0.6s_infinite_0.3s] h-1"></div>
                        </div>
                    )}
                </div>

                <button
                    onClick={() => onToggleBookmark(currentQuestion)}
                    className={`p-2 rounded-full transition-all duration-300 ${isBookmarked(currentQuestion) ? 'text-yellow-400 bg-yellow-400/10 scale-110' : 'text-slate-500 hover:text-yellow-300 hover:bg-yellow-400/5'}`}
                    aria-label={isBookmarked(currentQuestion) ? 'Remove bookmark' : 'Add bookmark (B)'}
                >
                    <BookmarkIcon filled={isBookmarked(currentQuestion)} />
                </button>
            </div>

            <h3 className="text-xl md:text-2xl font-bold mb-10 leading-relaxed text-slate-100">{currentQuestion.question}</h3>

            <div className="space-y-4">
                {currentQuestion.options.map((option, index) => (
                    <button
                        key={index}
                        onClick={() => handleAnswerSelect(option)}
                        disabled={quizState === 'answered'}
                        className={`group w-full text-left p-5 rounded-xl border-2 transition-all duration-200 text-base md:text-lg flex items-center gap-4 ${getOptionClass(option)}`}
                    >
                        <span className={`flex-shrink-0 w-8 h-8 rounded-full border-2 flex items-center justify-center font-mono font-bold text-sm transition-colors ${
                            selectedAnswer === option ? 'bg-primary text-white border-primary' : 'border-slate-700 text-slate-500 group-hover:border-primary group-hover:text-primary'
                        }`}>
                            {String.fromCharCode(65 + index)}
                        </span>
                        <span className="flex-grow">{option}</span>
                    </button>
                ))}
            </div>

            {quizState === 'answered' && (
                <div className="mt-10 border-t border-border pt-8 animate-fade-in-up">
                    <DexterExplains question={currentQuestion} userAnswer={results[results.length - 1]?.userAnswer} />
                </div>
            )}

            <div className="mt-10 flex flex-col sm:flex-row gap-4">
                {quizState === 'answering' ? (
                    <>
                        {mode !== 'Exam' && (
                            <button onClick={handleSkip} className="flex-1 order-2 sm:order-1 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold py-4 px-6 rounded-xl text-lg transition-all border border-border">
                                Skip (S)
                            </button>
                        )}
                        <button
                            onClick={handleSubmit}
                            disabled={!selectedAnswer}
                            className="flex-1 order-1 sm:order-2 bg-primary hover:bg-primary/90 text-primary-foreground font-extrabold py-4 px-6 rounded-xl text-lg disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-primary/20 transition-all hover:-translate-y-0.5"
                        >
                            Submit Answer (Enter)
                        </button>
                    </>
                ) : (
                    <button
                        onClick={handleNextQuestion}
                        className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-extrabold py-4 px-6 rounded-xl text-lg shadow-lg shadow-primary/20 transition-all hover:-translate-y-0.5 flex items-center justify-center gap-2"
                    >
                        {currentQuestionIndex + 1 === totalQuestionsInSet ? 'Finish Practice' : 'Next Question (N)'}
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                    </button>
                )}
            </div>
             {isLoading && currentQuestionIndex >= questions.length - 1 && <div className="mt-4"><Loader text="Thinking of the next challenge..." /></div>}
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;
const AVAILABLE_VOICES = ['Zephyr', 'Puck', 'Charon', 'Kore', 'Fenrir'];

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  // Speech states
  const [selectedVoice, setSelectedVoice] = useState('Zephyr');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  // Timer effect
  useEffect(() => {
    if (timer === 0) return;

    if (timeLeft <= 0) {
      finishQuiz();
      return;
    }

    const intervalId = setInterval(() => {
      setTimeLeft(prevTime => prevTime - 1);
    }, 1000);

    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  // Fetch questions effect
  useEffect(() => {
    const loadQuestions = async () => {
      setIsLoading(true);
      setError(null);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) {
          onQuizEnd([], 0);
          return;
        }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          const firstQuestion = await generateQuestion(difficulty, category);
          setQuestions([firstQuestion]);
          setIsLoading(false);
        } catch (err) {
          setError(err instanceof Error ? err.message : 'Failed to load question.');
          setIsLoading(false);
        }
      }
    };
    loadQuestions();
  }, [mode, difficulty, category, bookmarkedQuestions, onQuizEnd]);

  // Audio cleanup on unmount
  useEffect(() => {
    return () => {
      stopSpeaking();
    };
  }, []);

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
      try {
        audioSourceRef.current.stop();
      } catch (e) {
        // Already stopped
      }
      audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const handleReadAloud = async () => {
    // If already generating or speaking, the button acts as a Stop button
    if (isSpeaking || isGeneratingAudio) {
      stopSpeaking();
      return;
    }

    if (!currentQuestion) return;

    setIsGeneratingAudio(true);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const optionsText = currentQuestion.options
        .map((opt, i) => `Option ${String.fromCharCode(65 + i)}: ${opt}`)
        .join('. ');

      const textToRead = `${currentQuestion.question}. ... The options are: ${optionsText}`;

      const buffer = await generateSpeech(textToRead, selectedVoice, audioContextRef.current);

      setIsGeneratingAudio(false);
      setIsSpeaking(true);

      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setIsSpeaking(false);

      audioSourceRef.current = source;
      source.start();
    } catch (err) {
      console.error("Speech generation failed", err);
      setIsGeneratingAudio(false);
      setIsSpeaking(false);
    }
  };

  const handleAnswerSelect = (option: string) => {
    if (quizState === 'answering') {
      setSelectedAnswer(option);
    }
  };

  const handleSubmit = useCallback(() => {
    if (quizState !== 'answering' || selectedAnswer === null || !currentQuestion) return;

    const isCorrect = selectedAnswer === currentQuestion.answer;
    const newResult: ExamResult = {
      question: currentQuestion,
      userAnswer: selectedAnswer,
      isCorrect,
    };
    setResults(prev => [...prev, newResult]);
    setQuizState('answered');

  }, [quizState, selectedAnswer, currentQuestion]);

  const handleNextQuestion = useCallback(async () => {
    stopSpeaking();
    if (quizState !== 'answered') return;

    const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;

    if (currentQuestionIndex + 1 >= totalQuestionsInSet) {
      finishQuiz();
      return;
    }

    const nextIndex = currentQuestionIndex + 1;
    setSelectedAnswer(null);
    setQuizState('answering');
    setCurrentQuestionIndex(nextIndex);

    if (mode !== 'BookmarkReview' && nextIndex >= questions.length) {
        setIsLoading(true);
        setError(null);
        try {
            const nextQuestion = await generateQuestion(difficulty, category);
            setQuestions(prev => [...prev, nextQuestion]);
        } catch(err) {
            setError(err instanceof Error ? err.message : 'Failed to load next question.');
        } finally {
            setIsLoading(false);
        }
    }
  }, [quizState, currentQuestionIndex, questions.length, mode, bookmarkedQuestions.length, difficulty, category, finishQuiz]);

  const handleSkip = useCallback(() => {
    stopSpeaking();
    if (mode === 'Exam' || quizState !== 'answering' || !currentQuestion) return;

    const skippedResult: ExamResult = {
        question: currentQuestion,
        userAnswer: null,
        isCorrect: false
    };
    setResults(prev => [...prev, skippedResult]);
    setQuizState('answered');
  }, [mode, quizState, currentQuestion]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Enter' && selectedAnswer && quizState === 'answering') {
            handleSubmit();
        } else if (e.key.toLowerCase() === 'n' && quizState === 'answered') {
            handleNextQuestion();
        } else if (e.key.toLowerCase() === 's' && quizState === 'answering' && mode !== 'Exam') {
            handleSkip();
        } else if (e.key.toLowerCase() === 'b' && currentQuestion) {
            onToggleBookmark(currentQuestion);
        } else if (e.key.toLowerCase() === 'v') {
            handleReadAloud();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSubmit, handleNextQuestion, handleSkip, onToggleBookmark, selectedAnswer, quizState, mode, currentQuestion, isSpeaking, isGeneratingAudio, selectedVoice]);


  if (isLoading && questions.length === 0) {
    return <Loader text={mode === 'BookmarkReview' ? "Loading bookmarked questions..." : "Generating your first question..."} />;
  }

  if (error) {
    return (
      <div className="text-center p-8 bg-card rounded-lg border border-border">
        <h2 className="text-2xl font-bold text-danger mb-4">An Error Occurred</h2>
        <p className="text-slate-300 mb-6">{error}</p>
        <button onClick={() => onQuizEnd([], 0)} className="bg-primary hover:bg-primary/90 text-primary-foreground font-bold py-2 px-6 rounded-lg transition-colors">
          Back to Dashboard
        </button>
      </div>
    );
  }

  if (!currentQuestion) {
    return <Loader text="Preparing quiz..." />;
  }

  const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
  const progressPercentage = ((currentQuestionIndex + 1) / totalQuestionsInSet) * 100;

  const formatTime = (seconds: number) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getOptionClass = (option: string) => {
    const isSelected = selectedAnswer === option;
    if (quizState === 'answered') {
        const isCorrect = option === currentQuestion.answer;
        if (isCorrect) return 'bg-success/30 border-success text-foreground';
        if (isSelected) return 'bg-danger/30 border-danger text-foreground';
        return 'opacity-50 grayscale-[0.5]';
    }
    return isSelected
        ? 'bg-primary/20 border-primary ring-1 ring-primary text-foreground'
        : 'bg-card hover:bg-border border-border text-slate-300';
  };

  return (
    <div className="max-w-4xl mx-auto animate-fade-in px-2 sm:px-0">
        <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
            <h2 className="text-2xl font-bold tracking-tight">{mode === 'Exam' ? 'Exam Simulation' : mode === 'BookmarkReview' ? 'Bookmark Review' : 'Practice Session'}</h2>
            {timer > 0 && (
                <div className={`flex items-center gap-3 font-mono font-bold px-4 py-2 rounded-full border border-border shadow-inner ${timeLeft <= 60 ? 'text-danger bg-danger/10 animate-pulse' : 'text-slate-400 bg-card'}`}>
                    <StopwatchIcon className="w-5 h-5" />
                    <span className="text-xl">{formatTime(timeLeft)}</span>
                </div>
            )}
        </div>

        <div className="w-full bg-border rounded-full h-2 mb-8 shadow-inner overflow-hidden">
            <div className="bg-primary h-full rounded-full transition-all duration-500 ease-out shadow-[0_0_10px_rgba(99,102,241,0.5)]" style={{ width: `${progressPercentage}%` }}></div>
        </div>

        <div className="bg-card p-6 sm:p-10 rounded-2xl shadow-xl border border-border relative">
            <div className="flex justify-between items-center mb-8">
                <div className="flex flex-wrap items-center gap-3">
                    <span className="bg-primary/10 text-primary-light text-xs font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-primary/20">
                        Question {currentQuestionIndex + 1} of {totalQuestionsInSet}
                    </span>

                    {/* Voice Controls with Stop functionality */}
                    <div className="flex items-center gap-1 bg-background/50 p-1 rounded-lg border border-border group">
                        <div className="relative">
                            <select 
                              value={selectedVoice} 
                              onChange={(e) => setSelectedVoice(e.target.value)}
                              className="text-xs bg-transparent border-none focus:ring-0 text-slate-400 cursor-pointer pr-6 py-1 font-medium hover:text-slate-200 transition-colors appearance-none"
                              disabled={isSpeaking || isGeneratingAudio}
                              title="Select Voice"
                            >
                                {AVAILABLE_VOICES.map(v => <option key={v} value={v} className="bg-card text-foreground">{v}</option>)}
                            </select>
                            <div className="absolute inset-y-0 right-1 flex items-center pointer-events-none text-slate-500">
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </div>
                        </div>
                        <button
                          onClick={handleReadAloud}
                          className={`p-1.5 rounded-md transition-all ${
                            isSpeaking || isGeneratingAudio ? 'bg-danger text-white scale-110 shadow-lg shadow-danger/20' : 
                            'hover:bg-primary/20 text-primary-light'
                          }`}
                          title={isSpeaking || isGeneratingAudio ? "Stop (V)" : "Read Aloud (V)"}
                        >
                            {isSpeaking || isGeneratingAudio ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                        </button>
                    </div>

                    {/* Pulsating Dots Indicator */}
                    {(isSpeaking || isGeneratingAudio) && (
                        <div className="flex gap-1.5 items-center px-2 py-1 bg-primary/5 rounded-full border border-primary/10">
                            <span className="text-[10px] font-bold text-primary-light uppercase tracking-tighter mr-1">
                                {isGeneratingAudio ? "Generating" : "Playing"}
                            </span>
                            <div className="flex gap-1">
                                <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse"></span>
                                <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse [animation-delay:0.2s]"></span>
                                <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse [animation-delay:0.4s]"></span>
                            </div>
                        </div>
                    )}
                </div>

                <button
                    onClick={() => onToggleBookmark(currentQuestion)}
                    className={`p-2 rounded-full transition-all duration-300 ${isBookmarked(currentQuestion) ? 'text-yellow-400 bg-yellow-400/10 scale-110' : 'text-slate-500 hover:text-yellow-300 hover:bg-yellow-400/5'}`}
                    aria-label={isBookmarked(currentQuestion) ? 'Remove bookmark' : 'Add bookmark (B)'}
                >
                    <BookmarkIcon filled={isBookmarked(currentQuestion)} />
                </button>
            </div>

            <h3 className="text-xl md:text-2xl font-bold mb-10 leading-relaxed text-slate-100">{currentQuestion.question}</h3>

            <div className="space-y-4">
                {currentQuestion.options.map((option, index) => (
                    <button
                        key={index}
                        onClick={() => handleAnswerSelect(option)}
                        disabled={quizState === 'answered'}
                        className={`group w-full text-left p-5 rounded-xl border-2 transition-all duration-200 text-base md:text-lg flex items-center gap-4 ${getOptionClass(option)}`}
                    >
                        <span className={`flex-shrink-0 w-8 h-8 rounded-full border-2 flex items-center justify-center font-mono font-bold text-sm transition-colors ${
                            selectedAnswer === option ? 'bg-primary text-white border-primary' : 'border-slate-700 text-slate-500 group-hover:border-primary group-hover:text-primary'
                        }`}>
                            {String.fromCharCode(65 + index)}
                        </span>
                        <span className="flex-grow">{option}</span>
                    </button>
                ))}
            </div>

            {quizState === 'answered' && (
                <div className="mt-10 border-t border-border pt-8 animate-fade-in-up">
                    <DexterExplains question={currentQuestion} userAnswer={results[results.length - 1]?.userAnswer} />
                </div>
            )}

            <div className="mt-10 flex flex-col sm:flex-row gap-4">
                {quizState === 'answering' ? (
                    <>
                        {mode !== 'Exam' && (
                            <button onClick={handleSkip} className="flex-1 order-2 sm:order-1 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold py-4 px-6 rounded-xl text-lg transition-all border border-border">
                                Skip (S)
                            </button>
                        )}
                        <button
                            onClick={handleSubmit}
                            disabled={!selectedAnswer}
                            className="flex-1 order-1 sm:order-2 bg-primary hover:bg-primary/90 text-primary-foreground font-extrabold py-4 px-6 rounded-xl text-lg disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-primary/20 transition-all hover:-translate-y-0.5"
                        >
                            Submit Answer (Enter)
                        </button>
                    </>
                ) : (
                    <button
                        onClick={handleNextQuestion}
                        className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-extrabold py-4 px-6 rounded-xl text-lg shadow-lg shadow-primary/20 transition-all hover:-translate-y-0.5 flex items-center justify-center gap-2"
                    >
                        {currentQuestionIndex + 1 === totalQuestionsInSet ? 'Finish Practice' : 'Next Question (N)'}
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                    </button>
                )}
            </div>
             {isLoading && currentQuestionIndex >= questions.length - 1 && <div className="mt-4"><Loader text="Thinking of the next challenge..." /></div>}
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;
const AVAILABLE_VOICES = ['Zephyr', 'Puck', 'Charon', 'Kore', 'Fenrir'];

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Prefetch states
  const [nextPrefetchedQuestion, setNextPrefetchedQuestion] = useState<Question | null>(null);
  const [prefetchedAudioBuffer, setPrefetchedAudioBuffer] = useState<AudioBuffer | null>(null);
  const isPrefetchingQuestion = useRef(false);
  const isPrefetchingAudio = useRef(false);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  // Speech states
  const [selectedVoice, setSelectedVoice] = useState('Zephyr');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  // Timer effect
  useEffect(() => {
    if (timer === 0) return;

    if (timeLeft <= 0) {
      finishQuiz();
      return;
    }

    const intervalId = setInterval(() => {
      setTimeLeft(prevTime => prevTime - 1);
    }, 1000);

    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  // Initial question load
  useEffect(() => {
    const loadInitialQuestion = async () => {
      setIsLoading(true);
      setError(null);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) {
          onQuizEnd([], 0);
          return;
        }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          const firstQuestion = await generateQuestion(difficulty, category);
          setQuestions([firstQuestion]);
          setIsLoading(false);
        } catch (err) {
          setError(err instanceof Error ? err.message : 'Failed to load initial question.');
          setIsLoading(false);
        }
      }
    };
    loadInitialQuestion();
  }, [mode, difficulty, category, bookmarkedQuestions, onQuizEnd]);

  // Prefetching logic: Triggered whenever the question index changes
  useEffect(() => {
    if (isLoading || !currentQuestion) return;

    // 1. Prefetch Audio for Current Question
    const prefetchAudio = async () => {
      if (isPrefetchingAudio.current) return;
      setPrefetchedAudioBuffer(null);
      isPrefetchingAudio.current = true;

      try {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        const optionsText = currentQuestion.options
          .map((opt, i) => `Option ${String.fromCharCode(65 + i)}: ${opt}`)
          .join('. ');
        const textToRead = `${currentQuestion.question}. ... The options are: ${optionsText}`;

        const buffer = await generateSpeech(textToRead, selectedVoice, audioContextRef.current);
        setPrefetchedAudioBuffer(buffer);
      } catch (err) {
        console.warn("Background audio prefetch failed", err);
      } finally {
        isPrefetchingAudio.current = false;
      }
    };

    // 2. Prefetch Next Question (if in Practice/Exam mode)
    const prefetchNextQuestion = async () => {
      if (mode === 'BookmarkReview' || isPrefetchingQuestion.current) return;
      const totalInSet = TOTAL_QUESTIONS;
      if (currentQuestionIndex + 1 >= totalInSet) return;
      if (questions[currentQuestionIndex + 1]) return; // Already have it

      setNextPrefetchedQuestion(null);
      isPrefetchingQuestion.current = true;
      try {
        const nextQ = await generateQuestion(difficulty, category);
        setNextPrefetchedQuestion(nextQ);
      } catch (err) {
        console.warn("Background question prefetch failed", err);
      } finally {
        isPrefetchingQuestion.current = false;
      }
    };

    prefetchAudio();
    prefetchNextQuestion();
  }, [currentQuestionIndex, questions, isLoading, mode, difficulty, category, selectedVoice]);

  // Audio cleanup on unmount
  useEffect(() => {
    return () => {
      stopSpeaking();
    };
  }, []);

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
      try {
        audioSourceRef.current.stop();
      } catch (e) {
        // Already stopped
      }
      audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const playAudioBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    stopSpeaking();
    setIsSpeaking(true);
    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);
    source.onended = () => setIsSpeaking(false);
    audioSourceRef.current = source;
    source.start();
  };

  const handleReadAloud = async () => {
    if (isSpeaking || isGeneratingAudio) {
      stopSpeaking();
      return;
    }

    if (!currentQuestion) return;

    // Use prefetched buffer if available
    if (prefetchedAudioBuffer) {
      playAudioBuffer(prefetchedAudioBuffer);
      return;
    }

    // Fallback: Generate if not prefetched yet
    setIsGeneratingAudio(true);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const optionsText = currentQuestion.options
        .map((opt, i) => `Option ${String.fromCharCode(65 + i)}: ${opt}`)
        .join('. ');
      const textToRead = `${currentQuestion.question}. ... The options are: ${optionsText}`;

      const buffer = await generateSpeech(textToRead, selectedVoice, audioContextRef.current);
      setIsGeneratingAudio(false);
      playAudioBuffer(buffer);
    } catch (err) {
      console.error("Speech generation failed", err);
      setIsGeneratingAudio(false);
      setIsSpeaking(false);
    }
  };

  const handleAnswerSelect = (option: string) => {
    if (quizState === 'answering') {
      setSelectedAnswer(option);
    }
  };

  const handleSubmit = useCallback(() => {
    if (quizState !== 'answering' || selectedAnswer === null || !currentQuestion) return;

    const isCorrect = selectedAnswer === currentQuestion.answer;
    const newResult: ExamResult = {
      question: currentQuestion,
      userAnswer: selectedAnswer,
      isCorrect,
    };
    setResults(prev => [...prev, newResult]);
    setQuizState('answered');

  }, [quizState, selectedAnswer, currentQuestion]);

  const handleNextQuestion = useCallback(async () => {
    stopSpeaking();
    if (quizState !== 'answered') return;

    const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;

    if (currentQuestionIndex + 1 >= totalQuestionsInSet) {
      finishQuiz();
      return;
    }

    const nextIndex = currentQuestionIndex + 1;
    setSelectedAnswer(null);
    setQuizState('answering');

    // Check if we have the next question ready
    if (mode !== 'BookmarkReview') {
        if (questions[nextIndex]) {
            setCurrentQuestionIndex(nextIndex);
        } else if (nextPrefetchedQuestion) {
            setQuestions(prev => [...prev, nextPrefetchedQuestion]);
            setNextPrefetchedQuestion(null);
            setCurrentQuestionIndex(nextIndex);
        } else {
            // Hard fallback if prefetching is slow
            setIsLoading(true);
            try {
                const q = await generateQuestion(difficulty, category);
                setQuestions(prev => [...prev, q]);
                setCurrentQuestionIndex(nextIndex);
            } catch (err) {
                setError("Failed to load the next question.");
            } finally {
                setIsLoading(false);
            }
        }
    } else {
        // Bookmark review mode: questions already loaded
        setCurrentQuestionIndex(nextIndex);
    }
  }, [quizState, currentQuestionIndex, questions, mode, bookmarkedQuestions.length, nextPrefetchedQuestion, difficulty, category, finishQuiz]);

  const handleSkip = useCallback(() => {
    stopSpeaking();
    if (mode === 'Exam' || quizState !== 'answering' || !currentQuestion) return;

    const skippedResult: ExamResult = {
        question: currentQuestion,
        userAnswer: null,
        isCorrect: false
    };
    setResults(prev => [...prev, skippedResult]);
    setQuizState('answered');
  }, [mode, quizState, currentQuestion]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Enter' && selectedAnswer && quizState === 'answering') {
            handleSubmit();
        } else if (e.key.toLowerCase() === 'n' && quizState === 'answered') {
            handleNextQuestion();
        } else if (e.key.toLowerCase() === 's' && quizState === 'answering' && mode !== 'Exam') {
            handleSkip();
        } else if (e.key.toLowerCase() === 'b' && currentQuestion) {
            onToggleBookmark(currentQuestion);
        } else if (e.key.toLowerCase() === 'v') {
            handleReadAloud();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSubmit, handleNextQuestion, handleSkip, onToggleBookmark, selectedAnswer, quizState, mode, currentQuestion, isSpeaking, isGeneratingAudio, selectedVoice]);


  if (isLoading && questions.length === 0) {
    return <Loader text={mode === 'BookmarkReview' ? "Preparing your bookmarks..." : "Generating your first challenge..."} />;
  }

  if (error) {
    return (
      <div className="text-center p-8 bg-card rounded-lg border border-border">
        <h2 className="text-2xl font-bold text-danger mb-4">An Error Occurred</h2>
        <p className="text-slate-300 mb-6">{error}</p>
        <button onClick={() => onQuizEnd([], 0)} className="bg-primary hover:bg-primary/90 text-primary-foreground font-bold py-2 px-6 rounded-lg transition-colors">
          Back to Dashboard
        </button>
      </div>
    );
  }

  if (!currentQuestion) {
    return <Loader text="Preparing next question..." />;
  }

  const totalQuestionsInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
  const progressPercentage = ((currentQuestionIndex + 1) / totalQuestionsInSet) * 100;

  const formatTime = (seconds: number) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getOptionClass = (option: string) => {
    const isSelected = selectedAnswer === option;
    if (quizState === 'answered') {
        const isCorrect = option === currentQuestion.answer;
        if (isCorrect) return 'bg-success/30 border-success text-foreground';
        if (isSelected) return 'bg-danger/30 border-danger text-foreground';
        return 'opacity-50 grayscale-[0.5]';
    }
    return isSelected
        ? 'bg-primary/20 border-primary ring-1 ring-primary text-foreground'
        : 'bg-card hover:bg-border border-border text-slate-300';
  };

  return (
    <div className="max-w-4xl mx-auto animate-fade-in px-2 sm:px-0">
        <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
            <h2 className="text-2xl font-bold tracking-tight">{mode === 'Exam' ? 'Exam Simulation' : mode === 'BookmarkReview' ? 'Bookmark Review' : 'Practice Session'}</h2>
            {timer > 0 && (
                <div className={`flex items-center gap-3 font-mono font-bold px-4 py-2 rounded-full border border-border shadow-inner ${timeLeft <= 60 ? 'text-danger bg-danger/10 animate-pulse' : 'text-slate-400 bg-card'}`}>
                    <StopwatchIcon className="w-5 h-5" />
                    <span className="text-xl">{formatTime(timeLeft)}</span>
                </div>
            )}
        </div>

        <div className="w-full bg-border rounded-full h-2 mb-8 shadow-inner overflow-hidden">
            <div className="bg-primary h-full rounded-full transition-all duration-500 ease-out shadow-[0_0_10px_rgba(99,102,241,0.5)]" style={{ width: `${progressPercentage}%` }}></div>
        </div>

        <div className="bg-card p-6 sm:p-10 rounded-2xl shadow-xl border border-border relative">
            <div className="flex justify-between items-center mb-8">
                <div className="flex flex-wrap items-center gap-3">
                    <span className="bg-primary/10 text-primary-light text-xs font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-primary/20">
                        Question {currentQuestionIndex + 1} of {totalQuestionsInSet}
                    </span>

                    {/* Voice Controls with Stop functionality */}
                    <div className="flex items-center gap-1 bg-background/50 p-1 rounded-lg border border-border group">
                        <div className="relative">
                            <select 
                              value={selectedVoice} 
                              onChange={(e) => setSelectedVoice(e.target.value)}
                              className="text-xs bg-transparent border-none focus:ring-0 text-slate-400 cursor-pointer pr-6 py-1 font-medium hover:text-slate-200 transition-colors appearance-none"
                              disabled={isSpeaking || isGeneratingAudio}
                              title="Select Voice"
                            >
                                {AVAILABLE_VOICES.map(v => <option key={v} value={v} className="bg-card text-foreground">{v}</option>)}
                            </select>
                            <div className="absolute inset-y-0 right-1 flex items-center pointer-events-none text-slate-500">
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </div>
                        </div>
                        <button
                          onClick={handleReadAloud}
                          className={`p-1.5 rounded-md transition-all ${
                            isSpeaking || isGeneratingAudio ? 'bg-danger text-white scale-110 shadow-lg shadow-danger/20' : 
                            'hover:bg-primary/20 text-primary-light'
                          }`}
                          title={isSpeaking || isGeneratingAudio ? "Stop (V)" : "Read Aloud (V)"}
                        >
                            {isSpeaking || isGeneratingAudio ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                        </button>
                    </div>

                    {/* Pulsating Dots Indicator */}
                    {(isSpeaking || isGeneratingAudio) && (
                        <div className="flex gap-1.5 items-center px-2 py-1 bg-primary/5 rounded-full border border-primary/10">
                            <span className="text-[10px] font-bold text-primary-light uppercase tracking-tighter mr-1">
                                {isGeneratingAudio ? "Generating" : "Playing"}
                            </span>
                            <div className="flex gap-1">
                                <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse"></span>
                                <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse [animation-delay:0.2s]"></span>
                                <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse [animation-delay:0.4s]"></span>
                            </div>
                        </div>
                    )}
                </div>

                <button
                    onClick={() => onToggleBookmark(currentQuestion)}
                    className={`p-2 rounded-full transition-all duration-300 ${isBookmarked(currentQuestion) ? 'text-yellow-400 bg-yellow-400/10 scale-110' : 'text-slate-500 hover:text-yellow-300 hover:bg-yellow-400/5'}`}
                    aria-label={isBookmarked(currentQuestion) ? 'Remove bookmark' : 'Add bookmark (B)'}
                >
                    <BookmarkIcon filled={isBookmarked(currentQuestion)} />
                </button>
            </div>

            <h3 className="text-xl md:text-2xl font-bold mb-10 leading-relaxed text-slate-100">{currentQuestion.question}</h3>

            <div className="space-y-4">
                {currentQuestion.options.map((option, index) => (
                    <button
                        key={index}
                        onClick={() => handleAnswerSelect(option)}
                        disabled={quizState === 'answered'}
                        className={`group w-full text-left p-5 rounded-xl border-2 transition-all duration-200 text-base md:text-lg flex items-center gap-4 ${getOptionClass(option)}`}
                    >
                        <span className={`flex-shrink-0 w-8 h-8 rounded-full border-2 flex items-center justify-center font-mono font-bold text-sm transition-colors ${
                            selectedAnswer === option ? 'bg-primary text-white border-primary' : 'border-slate-700 text-slate-500 group-hover:border-primary group-hover:text-primary'
                        }`}>
                            {String.fromCharCode(65 + index)}
                        </span>
                        <span className="flex-grow">{option}</span>
                    </button>
                ))}
            </div>

            {quizState === 'answered' && (
                <div className="mt-10 border-t border-border pt-8 animate-fade-in-up">
                    <DexterExplains question={currentQuestion} userAnswer={results[results.length - 1]?.userAnswer} />
                </div>
            )}

            <div className="mt-10 flex flex-col sm:flex-row gap-4">
                {quizState === 'answering' ? (
                    <>
                        {mode !== 'Exam' && (
                            <button onClick={handleSkip} className="flex-1 order-2 sm:order-1 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold py-4 px-6 rounded-xl text-lg transition-all border border-border">
                                Skip (S)
                            </button>
                        )}
                        <button
                            onClick={handleSubmit}
                            disabled={!selectedAnswer}
                            className="flex-1 order-1 sm:order-2 bg-primary hover:bg-primary/90 text-primary-foreground font-extrabold py-4 px-6 rounded-xl text-lg disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-primary/20 transition-all hover:-translate-y-0.5"
                        >
                            Submit Answer (Enter)
                        </button>
                    </>
                ) : (
                    <button
                        onClick={handleNextQuestion}
                        className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-extrabold py-4 px-6 rounded-xl text-lg shadow-lg shadow-primary/20 transition-all hover:-translate-y-0.5 flex items-center justify-center gap-2"
                    >
                        {currentQuestionIndex + 1 === totalQuestionsInSet ? 'Finish Practice' : 'Next Question (N)'}
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                    </button>
                )}
            </div>
             {isLoading && currentQuestionIndex >= questions.length - 1 && <div className="mt-4"><Loader text="Preparing the next challenge..." /></div>}
             {isPrefetchingQuestion.current && quizState === 'answering' && (
                 <p className="mt-4 text-xs text-center text-slate-500 animate-pulse">Background pre-fetching next question for you...</p>
             )}
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

// Implemented the main App component to handle state management, view routing, data persistence, and theme.
import React, { useState, useEffect, useCallback } from 'react';
import { Dashboard } from './components/Dashboard';
import { Quiz } from './components/Quiz';
import { SessionReview } from './components/SessionReview';
import { BookmarkedQuestions } from './components/BookmarkedQuestions';
import type { ProgressData, Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from './types';
import { PowerBiIcon } from './components/icons/PowerBiIcon';
import { PerformanceSummaryModal } from './components/PerformanceSummaryModal';
import { ThemeToggle } from './components/ThemeToggle';
import { PracticeExamDownloader } from './components/PracticeExamDownloader';

type View = 'dashboard' | 'quiz' | 'review' | 'bookmarks';
type Theme = 'light' | 'dark';

const INITIAL_PROGRESS: ProgressData = {
  totalQuestions: 0,
  totalCorrect: 0,
  currentStreak: 0,
  categoryStats: {
    'Prepare the data': { correct: 0, total: 0 },
    'Model the data': { correct: 0, total: 0 },
    'Visualize and analyze the data': { correct: 0, total: 0 },
    'Deploy and maintain assets': { correct: 0, total: 0 },
  },
  bookmarkedQuestions: [],
  accuracyHistory: [],
  examHistory: [],
};

const APP_DATA_KEY = 'pl300-progress';

interface SessionSummary {
    score: number;
    total: number;
    accuracy: string;
    timeTaken: number;
}

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [progressData, setProgressData] = useState<ProgressData>(INITIAL_PROGRESS);
  const [quizSettings, setQuizSettings] = useState<{ difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }>({
    difficulty: 'Adaptive',
    timer: 15,
    mode: 'Practice',
    category: 'All',
  });
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [showSummaryModal, setShowSummaryModal] = useState(false);
  const [sessionSummary, setSessionSummary] = useState<SessionSummary | null>(null);
  const [theme, setTheme] = useState<Theme>('dark');
  const [showPracticeExamModal, setShowPracticeExamModal] = useState(false);

  // Effect to load theme on initial load
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as Theme | null;
    const initialTheme = savedTheme || 'dark';
    setTheme(initialTheme);
  }, []);

  // Effect to apply theme class and save to localStorage
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  // Effect to load data on initial load
  useEffect(() => {
    try {
      const savedData = localStorage.getItem(APP_DATA_KEY);
      if (savedData) {
        const parsedData = JSON.parse(savedData);
        const mergedData: ProgressData = {
          ...INITIAL_PROGRESS,
          ...parsedData,
          categoryStats: { ...INITIAL_PROGRESS.categoryStats, ...(parsedData.categoryStats || {}), },
          bookmarkedQuestions: parsedData.bookmarkedQuestions || [],
          accuracyHistory: parsedData.accuracyHistory || [],
          examHistory: parsedData.examHistory || [],
        };
        setProgressData(mergedData);
      } else {
        setProgressData(INITIAL_PROGRESS);
      }
    } catch (error) {
      console.error("Failed to load progress data. Resetting.", error);
      setProgressData(INITIAL_PROGRESS);
    }
  }, []);

  // Effect to save data whenever it changes
  useEffect(() => {
    try {
      localStorage.setItem(APP_DATA_KEY, JSON.stringify(progressData));
    } catch (error) {
      console.error("Failed to save progress data", error);
    }
  }, [progressData]);

  const handleStartQuiz = useCallback((settings: { difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }) => {
    setQuizSettings(settings);
    setView('quiz');
  }, []);

  const handleQuizEnd = useCallback((results: ExamResult[], timeTaken: number) => {
    setExamResults(results);

    if (results.length === 0) {
        setView('review');
        return;
    }

    setProgressData(prevData => {
      const newData = { ...prevData, categoryStats: JSON.parse(JSON.stringify(prevData.categoryStats)), accuracyHistory: [...(prevData.accuracyHistory || [])], };
      let newStreak = prevData.currentStreak;
      let sessionCorrect = 0;

      results.forEach(result => {
        newData.totalQuestions += 1;
        const category = result.question.category;
        if (!newData.categoryStats[category]) {
           newData.categoryStats[category] = { correct: 0, total: 0 };
        }
        newData.categoryStats[category].total += 1;

        if (result.isCorrect) {
          newData.totalCorrect += 1;
          newData.categoryStats[category].correct += 1;
          newStreak += 1;
          sessionCorrect += 1;
        } else {
          newStreak = 0;
        }
      });
      newData.currentStreak = newStreak;

      const sessionAccuracy = (sessionCorrect / results.length) * 100;
      newData.accuracyHistory.push({
          session: newData.accuracyHistory.length + 1,
          accuracy: sessionAccuracy,
      });

      const newHistory = [...(prevData.examHistory || []), results].slice(-10);
      newData.examHistory = newHistory;

      return newData;
    });

    const score = results.filter(r => r.isCorrect).length;
    const total = results.length;
    const accuracy = total > 0 ? ((score / total) * 100).toFixed(0) : '0';

    setSessionSummary({ score, total, accuracy, timeTaken });
    setShowSummaryModal(true);
  }, []);

  const handleCloseSummaryModal = useCallback(() => {
    setShowSummaryModal(false);
    setView('review');
  }, []);

  const handleToggleBookmark = useCallback((question: Question) => {
    setProgressData(prevData => {
      const isBookmarked = prevData.bookmarkedQuestions.some(bq => bq.question === question.question);
      return {
        ...prevData,
        bookmarkedQuestions: isBookmarked
          ? prevData.bookmarkedQuestions.filter(bq => bq.question !== question.question)
          : [...prevData.bookmarkedQuestions, question],
      };
    });
  }, []);

  const isBookmarked = useCallback((question: Question) => progressData.bookmarkedQuestions.some(bq => bq.question === question.question), [progressData.bookmarkedQuestions]);
  const handleViewBookmarks = useCallback(() => setView('bookmarks'), []);
  const handleStartBookmarkReview = useCallback(() => handleStartQuiz({ difficulty: 'Easy', timer: 0, mode: 'BookmarkReview', category: 'All' }), [handleStartQuiz]);
  const handleBackToDashboard = useCallback(() => { setExamResults([]); setSessionSummary(null); setView('dashboard'); }, []);
  const handleResetProgress = useCallback(() => {
    if (window.confirm("Are you sure you want to reset all your progress? This action cannot be undone.")) {
        setProgressData(INITIAL_PROGRESS);
        setView('dashboard');
    }
  }, []);

  const renderAppContent = () => {
    switch (view) {
      case 'quiz':
        return <Quiz {...quizSettings} bookmarkedQuestions={progressData.bookmarkedQuestions} onQuizEnd={handleQuizEnd} onToggleBookmark={handleToggleBookmark} isBookmarked={isBookmarked} />;
      case 'review':
        return <SessionReview results={examResults} onBackToDashboard={handleBackToDashboard} theme={theme} />;
      case 'bookmarks':
        return <BookmarkedQuestions questions={progressData.bookmarkedQuestions} onToggleBookmark={handleToggleBookmark} onBackToDashboard={handleBackToDashboard} onStartQuiz={handleStartBookmarkReview} />;
      case 'dashboard':
      default:
        return <Dashboard 
                    progressData={progressData} 
                    onStartQuiz={handleStartQuiz} 
                    onViewBookmarks={handleViewBookmarks} 
                    onResetProgress={handleResetProgress} 
                    onDownloadPracticeExam={() => setShowPracticeExamModal(true)}
                    theme={theme} />;
    }
  };

  return (
    <div className="bg-background text-foreground min-h-screen font-sans">
      <header className="py-4 border-b border-border">
        <div className="max-w-screen-2xl mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <PowerBiIcon className="w-10 h-10" />
            <h1 className="text-2xl md:text-3xl font-bold tracking-tight">PL-300 Power Practice</h1>
          </div>
          <ThemeToggle theme={theme} toggleTheme={toggleTheme} />
        </div>
      </header>
      <main className="max-w-screen-2xl mx-auto p-4 md:p-8">
        {renderAppContent()}
      </main>
       {showSummaryModal && sessionSummary && (
            <PerformanceSummaryModal summary={sessionSummary} onClose={handleCloseSummaryModal} />
        )}
        {showPracticeExamModal && (
            <PracticeExamDownloader onClose={() => setShowPracticeExamModal(false)} />
        )}
      <footer className="text-center py-4 text-slate-500 dark:text-slate-400 text-sm border-t border-border mt-8">
        <p>Powered by Gemini & AI Studio. Built for learning.</p>
      </footer>
    </div>
  );
};

export default App;

