interface DashboardProps {
    progressData: ProgressData;
    onStartQuiz: (settings: { difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }) => void;
    onViewBookmarks: () => void;
    onViewStudyHub: () => void;
    onResetProgress: () => void;
    onDownloadPracticeExam: () => void;
    theme: 'light' | 'dark';
}

interface SearchableItem {
    question: Question;
    isBookmarked: boolean;
    history: ExamResult[];
}


export const Dashboard: React.FC<DashboardProps> = ({ progressData, onStartQuiz, onViewBookmarks, onViewStudyHub, onResetProgress, onDownloadPracticeExam, theme }) => {
    const [difficulty, setDifficulty] = useState<Difficulty>('Adaptive');
    const [timer, setTimer] = useState<TimerSetting>(15);
    const [category, setCategory] = useState<QuestionCategoryFilter>('All');
    const [searchQuery, setSearchQuery] = useState('');
    const [activeSearchIndex, setActiveSearchIndex] = useState<string | null>(null);

    const overallAccuracy = progressData.totalQuestions > 0 ? ((progressData.totalCorrect / progressData.totalQuestions) * 100).toFixed(1) + '%' : 'N/A';
    const readinessScore = calculateReadinessScore(progressData);

    const searchableData: SearchableItem[] = useMemo(() => {
        const questionMap = new Map<string, SearchableItem>();

        const addOrGetQuestion = (q: Question) => {
            if (!questionMap.has(q.question)) {
                questionMap.set(q.question, {
                    question: q,
                    isBookmarked: false,
                    history: []
                });
            }
            return questionMap.get(q.question)!;
        };

        progressData.bookmarkedQuestions.forEach(q => {
            const item = addOrGetQuestion(q);
            item.isBookmarked = true;
        });

        (progressData.examHistory || []).flat().forEach(result => {
            const item = addOrGetQuestion(result.question);
            // Avoid adding duplicate history entries
            if (!item.history.some(h => h.userAnswer === result.userAnswer && h.question.question === result.question.question)) {
                item.history.push(result);
            }
        });

        return Array.from(questionMap.values());
    }, [progressData.bookmarkedQuestions, progressData.examHistory]);

    const filteredResults = useMemo(() => {
        const trimmedQuery = searchQuery.trim();
        if (trimmedQuery.length < 3) {
            return [];
        }
        const lowerCaseQuery = trimmedQuery.toLowerCase();
        return searchableData.filter(item => 
            item.question.question.toLowerCase().includes(lowerCaseQuery) ||
            item.question.options.some(opt => opt.toLowerCase().includes(lowerCaseQuery))
        );
    }, [searchQuery, searchableData]);


    const getStreakStyles = (streak: number) => {
        if (streak >= 10) return { color: 'text-red-500', animation: 'animate-pulse' };
        if (streak >= 5) return { color: 'text-orange-400', animation: '' };
        if (streak > 0) return { color: 'text-yellow-400', animation: '' };
        return { color: 'text-slate-500 dark:text-slate-400', animation: '' };
    };
    const streakStyles = getStreakStyles(progressData.currentStreak);

    const handleStartPractice = () => {
        onStartQuiz({ difficulty, timer, mode: 'Practice', category });
    };

    const handleStartExam = () => {
        onStartQuiz({ difficulty: 'Hard', timer: 10, mode: 'Exam', category: 'All' });
    };

    const handleResetPracticeSettings = () => {
        setDifficulty('Adaptive');
        setTimer(15);
