                    <h3 className="text-xl font-bold mb-4">At a Glance</h3>
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <PencilIcon className="w-6 h-6 text-slate-500 dark:text-slate-400" />
                                <span className="font-semibold text-slate-700 dark:text-slate-300">Total Questions</span>
                            </div>
                            <div className="text-2xl font-bold">{progressData.totalQuestions}</div>
                        </div>
                        <hr className="border-border/50" />
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <TargetIcon className="w-6 h-6 text-slate-500 dark:text-slate-400" />
                                <span className="font-semibold text-slate-700 dark:text-slate-300">Overall Accuracy</span>
                            </div>
                            <div className="text-2xl font-bold">{overallAccuracy}</div>
                        </div>
                        <hr className="border-border/50" />
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <FlameIcon className={`w-7 h-7 transition-colors ${streakStyles.color}`} />
                                <span className={`font-semibold text-slate-700 dark:text-slate-300 ${streakStyles.color}`}>Current Streak</span>
                            </div>
                            <div className={`text-2xl font-bold ${streakStyles.color}`}>{progressData.currentStreak}</div>
                        </div>
                    </div>
                </div>

                <StudyGuide categoryStats={progressData.categoryStats} />

                <div className="space-y-3">
                    <button
                        onClick={onViewBookmarks}
                        className="w-full bg-card hover:bg-border border border-border p-4 rounded-lg flex items-center justify-center gap-2 font-semibold"
                    >
                        <BookmarkIcon filled={true} className="text-yellow-400" />
                        View Bookmarks ({progressData.bookmarkedQuestions.length})
                    </button>
                    <button
                        onClick={onDownloadPracticeExam}
                        className="w-full bg-card hover:bg-border border border-border p-4 rounded-lg flex items-center justify-center gap-2 font-semibold"
                    >
                        <DocumentDownloadIcon className="text-primary" />
                        Download Practice Exam
                    </button>
                </div>

                <div className="flex justify-center pt-4">
                    <button
                        onClick={onResetProgress}
                        className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400 hover:text-danger hover:underline"
                    >
                        <TrashIcon className="w-4 h-4" /> Reset All Progress
                    </button>
                </div>
            </aside>
        </div>
    );
};

import React, { useState } from 'react';
