// Implemented the Gemini service for question, study guide, and speech generation.
import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Question, Difficulty, QuestionCategory, StudyGuideLength } from '../types';

// Per guidelines, create a new GoogleGenAI instance for each call to ensure the latest API key is used.
const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY! });

// Helper functions for audio decoding as per guidelines
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

// Schema for the question generation to ensure structured output
const questionSchema = {
  type: Type.OBJECT,
  properties: {
    question: { type: Type.STRING, description: 'The question text.' },
    options: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: 'An array of 4 multiple-choice options.'
    },
    answer: { type: Type.STRING, description: 'The correct option from the options array.' },
    explanation: { type: Type.STRING, description: 'A detailed explanation for why the answer is correct.' },
    category: {
      type: Type.STRING,
      description: 'The category of the question.',
      enum: ['Prepare the data', 'Model the data', 'Visualize and analyze the data', 'Deploy and maintain assets']
    },
    difficulty: {
      type: Type.STRING,
      description: 'The difficulty of the question.',
      enum: ['Easy', 'Medium', 'Hard']
    }
  },
  required: ['question', 'options', 'answer', 'explanation', 'category', 'difficulty']
};

export const generateQuestion = async (difficulty: Difficulty, category: QuestionCategory | 'All' = 'All'): Promise<Question> => {
    // Per guidelines, use gemini-3-pro-preview for complex text tasks
    const model = 'gemini-3-pro-preview';

    let categoryPromptSection = `
    The question must be relevant to one of the four main skill areas:
    1. Prepare the data
    2. Model the data
    3. Visualize and analyze the data
    4. Deploy and maintain assets`;

    if (category !== 'All') {
        categoryPromptSection = `The question must be relevant to the skill area: "${category}".`;
    }

    const prompt = `Generate a unique, high-quality, multiple-choice question for the Microsoft Power BI PL-300 certification exam.

    ${categoryPromptSection}

    The desired difficulty for this question is: ${difficulty === 'Adaptive' ? 'varied' : difficulty}.

    The question should be practical and scenario-based. Provide exactly 4 distinct options. Ensure only one option is correct.
    Provide a clear and concise explanation for the correct answer.

    Random seed token: ${Math.random().toString(36).substring(7)}

    Return the output in the specified JSON format.`;

    const schemaForRequest = JSON.parse(JSON.stringify(questionSchema));
    if (category !== 'All') {
        schemaForRequest.properties.category.enum = [category];
    }

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: schemaForRequest,
                temperature: 1.0, // High temperature for variety
            },
        });

        const text = response.text;
        const generatedQuestion = JSON.parse(text);

        if (!generatedQuestion.question || !Array.isArray(generatedQuestion.options) || generatedQuestion.options.length !== 4 || !generatedQuestion.answer || !generatedQuestion.explanation || !generatedQuestion.category || !generatedQuestion.difficulty) {
            throw new Error("Received malformed question data from API.");
        }
        if (!generatedQuestion.options.includes(generatedQuestion.answer)) {
             throw new Error("The provided answer is not in the options list.");
        }

        return generatedQuestion as Question;
    } catch (error) {
        console.error("Error generating question:", error);
        throw new Error("Failed to generate a new question. Please try again.");
    }
};

export const generateSpeech = async (text: string, voiceName: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    const ai = getAiClient();
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Say clearly and naturally: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) {
            throw new Error("No audio data received from the API.");
        }

        const decodedAudio = decodeBase64(base64Audio);
        const audioBuffer = await decodeAudioData(
            decodedAudio,
            audioContext,
            24000,
            1
        );
        return audioBuffer;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw error;
    }
};

export const getPersonalizedFeedback = async (question: Question, userAnswer: string): Promise<string> => {
    const model = 'gemini-3-flash-preview';
    const isCorrect = question.answer === userAnswer;

    const prompt = `A student has answered a question about Power BI. Your task is to provide personalized feedback in an encouraging and professional tone.

    Question: "${question.question}"
    Correct Answer: "${question.answer}"
    Student's Answer: "${userAnswer}"

    ${isCorrect 
        ? `The student answered correctly. Start by confirming their answer is correct (e.g., "That's correct!"). Then, briefly reinforce WHY their answer is correct, perhaps adding a small extra tip related to the concept.`
        : `The student's answer was incorrect. Start with an encouraging tone (e.g., "Not quite, but this is a common point of confusion."). Explain why their choice, "${userAnswer}", is incorrect and then clearly explain why "${question.answer}" is the correct choice. Keep it positive and focused on learning.`
    }

    Keep the feedback concise and helpful.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({ model, contents: prompt });
        const feedback = response.text;
        if (!feedback) {
            throw new Error("Received empty feedback from API.");
        }
        return feedback;
    } catch (error) {
        console.error("Error generating feedback:", error);
        throw new Error("Failed to generate personalized feedback.");
    }
};

export const generateStudyGuideStream = async (
    category: QuestionCategory | 'All', 
    length: StudyGuideLength, 
    onChunk: (chunk: string) => void
): Promise<void> => {

    const model = length === 'Concise' ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview';

    let lengthPrompt = '';
    switch(length) {
        case 'Concise':
            lengthPrompt = 'Keep the entire guide concise and under 200 words.';
            break;
        case 'Detailed':
            lengthPrompt = 'The guide should be detailed, around 500-700 words.';
            break;
        case 'Comprehensive':
            lengthPrompt = 'The guide should be very comprehensive, around 1000-1500 words.';
            break;
    }

    let categoryPrompt = '';
    if (category === 'All') {
        categoryPrompt = `The guide must cover all four main skill areas of the exam:
        1. Prepare the data
        2. Model the data
        3. Visualize and analyze the data
        4. Deploy and maintain assets

        For each skill area, provide an overview, detailed bullet points, and practical tips.`;
    } else {
        categoryPrompt = `The guide should focus exclusively on the topic: "${category}".`;
    }

    const prompt = `Create a high-quality study guide for the Microsoft Power BI PL-300 certification exam.

    ${categoryPrompt}

    **Crucially, you must include practical, real-world examples and, where appropriate, mini case studies to illustrate the key concepts.** This is essential for helping the user understand the material in a practical context.

    Use Markdown for formatting. Use headings (#, ##), bolding, and lists to create a clear, readable structure. The tone should be professional, encouraging, and easy to understand.

    Unique Token: ${Date.now()}

    ${lengthPrompt}`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContentStream({
            model: model,
            contents: prompt,
            config: {
                temperature: 0.8,
            },
        });

        for await (const chunk of response) {
            const chunkText = chunk.text;
            if (chunkText) {
                onChunk(chunkText);
            }
        }
    } catch (error) {
        console.error("Error generating study guide:", error);
        throw new Error("Failed to generate the study guide. Please try again.");
    }
};

export const generateRelatedTips = async (question: Question): Promise<string[]> => {
    const model = 'gemini-3-flash-preview';
    const tipsSchema = {
        type: Type.OBJECT,
        properties: {
            tips: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
                description: 'An array of 2-3 concise, practical tips related to the question\'s topic.'
            }
        },
        required: ['tips']
    };

    const prompt = `Based on this PL-300 exam question, generate 2-3 additional, concise, and practical tips. The tips should help a student better understand the core concept.

    Question: "${question.question}"
    Topic: "${question.category}"

    Focus on providing actionable advice or highlighting common pitfalls related to the topic.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: tipsSchema,
                temperature: 0.8,
            },
        });

        const text = response.text;
        const result = JSON.parse(text);

        if (!result.tips || !Array.isArray(result.tips)) {
            throw new Error("Received malformed tips data from API.");
        }

        return result.tips as string[];
    } catch (error) {
        console.error("Error generating related tips:", error);
        // Don't throw, return empty array to avoid breaking UI for a non-critical feature
        return []; 
    }
};

export const generatePracticeExamStream = async (onChunk: (chunk: string) => void, questionCount: number = 25): Promise<void> => {
    const model = 'gemini-3-pro-preview';

    const prompt = `Generate a full, unique practice exam for the PL-300 Power BI certification. The exam MUST contain exactly ${questionCount} high-quality, scenario-based, multiple-choice questions. 

    IMPORTANT: Every time you are asked, generate a COMPLETELY NEW set of questions. Do not repeat questions from previous sessions. Use diverse scenarios across finance, retail, healthcare, and tech.

    Ensure the questions follow the actual PL-300 weighting:
    - Prepare the data (25-30%)
    - Model the data (25-30%)
    - Visualize and analyze the data (25-30%)
    - Deploy and maintain assets (15-20%)

    Format for EACH question:
    1. Question Number (e.g., "**Question 1 [Domain: Model the Data]:**").
    2. Scenario Description (if applicable) and the Question text.
    3. Options A, B, C, D.
    4. **Correct Answer:** Label only (e.g. B).
    5. **Explanation:** Deep dive into why it's correct and why others are distractions. Mention specific Power BI features like DAX functions (CALCULATE, RELATED, etc.), Power Query transforms, or Workspace settings.

    Unique ID for this specific generation request: ${Math.random().toString(36).substring(2, 15)}

    Format the output as a clean Markdown document.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContentStream({
            model: model,
            contents: prompt,
            config: {
                temperature: 1.0, // Maximum randomness to ensure a fresh set
            },
        });

        for await (const chunk of response) {
            const chunkText = chunk.text;
            if (chunkText) {
                onChunk(chunkText);
            }
        }
    } catch (error) {
        console.error("Error generating practice exam:", error);
        throw new Error("Failed to generate the practice exam. Please try again.");
    }
};

