// Declaration for FileSaver.js, loaded via CDN
declare const saveAs: (blob: Blob, filename: string) => void;

interface PracticeExamDownloaderProps {
    onClose: () => void;
}

const ANSWER_START_TAG = '[ANSWER_START]';
const ANSWER_END_TAG = '[ANSWER_END]';

export const PracticeExamDownloader: React.FC<PracticeExamDownloaderProps> = ({ onClose }) => {
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState('');
    const [examContent, setExamContent] = useState('');
    const [includeAnswers, setIncludeAnswers] = useState(true);
    const examContentRef = useRef('');

    // Voice related state
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    const handleGenerate = async () => {
        stopSpeaking();
        setIsGenerating(true);
        setError('');
        setExamContent('');
        examContentRef.current = '';

        try {
            await generatePracticeExamStream((chunk) => {
                examContentRef.current += chunk;
                setExamContent(examContentRef.current);
            });
        } catch (err) {
            setError(err instanceof Error ? err.message : 'An unknown error occurred.');
            setIsGenerating(false);
        } finally {
            setIsGenerating(false);
        }
    };

    const downloadMarkdown = () => {
        const contentToSave = includeAnswers 
            ? examContentRef.current.replace(/\[ANSWER_(START|END)\]/g, '')
            : examContentRef.current.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answer hidden for practice)*\n');

        const blob = new Blob([contentToSave], { type: 'text/markdown;charset=utf-8' });
        saveAs(blob, 'PL-300_Practice_Exam.md');
        onClose();
    };

    const handlePrintToPdf = () => {
        // Trigger browser's native print dialog. 
        // Modern browsers allow "Save as PDF" from here.
        window.print();
    };

    const stopSpeaking = () => {
        if (audioSourceRef.current) {
            try { audioSourceRef.current.stop(); } catch (e) {}
            audioSourceRef.current = null;
        }
        setIsSpeaking(false);
        setIsGeneratingAudio(false);
    };

    const handleReadAloud = async () => {
        if (isSpeaking || isGeneratingAudio) {
            stopSpeaking();
            return;
        }

        if (!examContent) return;

        setIsGeneratingAudio(true);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }

            // Just read the first few hundred chars for safety/latency, or the whole thing?
            // Usually we'd read chunks, but let's take a simplified approach.
            const textToRead = examContent.substring(0, 5000).replace(/\[ANSWER_(START|END)\]/g, '');

            const buffer = await generateSpeech(textToRead, 'Zephyr', audioContextRef.current);
            setIsGeneratingAudio(false);

            if (!audioContextRef.current) return;
            setIsSpeaking(true);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => setIsSpeaking(false);
            audioSourceRef.current = source;
            source.start();
        } catch (err) {
            console.error("Speech generation failed", err);
            setIsGeneratingAudio(false);
            setIsSpeaking(false);
        }
    };

    // Cleaned content for preview
    const processedPreview = useMemo(() => {
        if (includeAnswers) {
            return examContent.replace(/\[ANSWER_(START|END)\]/g, '');
        }
        return examContent.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answer hidden for practice)*\n');
    }, [examContent, includeAnswers]);

    // Printable version with specific formatting
    const printableContent = useMemo(() => {
        let content = examContent;
        if (!includeAnswers) {
            content = content.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answer section removed)*\n');
        } else {
            content = content.replace(/\[ANSWER_START\]/g, '\n<div class="answer-block">')
                             .replace(/\[ANSWER_END\]/g, '</div>\n');
        }
        return content;
    }, [examContent, includeAnswers]);

    return (
        <div 
            className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4 print:p-0 print:bg-white print:static" 
            onClick={isGenerating ? undefined : onClose}
            role="dialog"
            aria-modal="true"
        >
            <div 
                className="bg-card rounded-2xl shadow-2xl w-full max-w-3xl h-[90vh] overflow-hidden flex flex-col animate-pop-in print:hidden" 
                onClick={e => e.stopPropagation()}
            >
                <div className="p-6 border-b border-border flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-3">
                        <DocumentDownloadIcon className="text-primary w-8 h-8" />
                        <div>
                            <h2 className="text-xl font-bold tracking-tight">Practice Exam Downloader</h2>
                            <p className="text-xs text-slate-400">Questions & Answers interlinked</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-white text-3xl leading-none">&times;</button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
                    {!examContent && !isGenerating ? (
                        <div className="py-20 text-center">
                            <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-6">
                                <SparklesIcon className="w-10 h-10 text-primary" />
                            </div>
                            <h3 className="text-xl font-bold mb-2">Generate Your Custom Exam</h3>
                            <p className="text-slate-400 max-w-sm mx-auto mb-8">
                                Create a professional set where each question is immediately followed by its correct answer and explanation.
                            </p>
                            <button
                                onClick={handleGenerate}
                                className="bg-primary hover:bg-primary/90 text-white font-extrabold py-4 px-10 rounded-2xl shadow-xl shadow-primary/20 transition-all hover:scale-105 active:scale-95"
                            >
                                Start AI Generation
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-6">
                            {/* Toolbar */}
                            <div className="sticky top-0 z-10 bg-card/80 backdrop-blur-md p-3 border border-border rounded-xl flex flex-wrap items-center justify-between gap-4">
                                <div className="flex items-center gap-4">
                                    <label className="flex items-center gap-2 text-sm cursor-pointer select-none font-semibold">
                                        <input 
                                            type="checkbox" 
                                            checked={includeAnswers} 
                                            onChange={(e) => setIncludeAnswers(e.target.checked)}
                                            className="w-4 h-4 rounded text-primary focus:ring-primary border-slate-700 bg-slate-800"
                                        />
                                        Show Answers
                                    </label>
                                    <button 
                                        onClick={handleReadAloud}
                                        className={`flex items-center gap-2 text-sm font-bold px-4 py-2 rounded-lg transition-all ${
                                            isSpeaking || isGeneratingAudio ? 'bg-danger text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
                                        }`}
                                    >
                                        {isSpeaking || isGeneratingAudio ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                                        {isGeneratingAudio ? 'Synthesizing...' : isSpeaking ? 'Stop Reading' : 'Listen'}
                                    </button>
                                </div>

                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={handlePrintToPdf}
