                                    >
                                        Save .MD
                                    </button>
                                </div>
                            </div>

                            {/* Content Preview */}
                            <div className="bg-background/50 p-8 rounded-2xl border border-border shadow-inner font-serif leading-relaxed text-slate-200">
                                <div className="prose prose-invert max-w-none whitespace-pre-wrap">
