    const [fontSize, setFontSize] = useState<FontSize>('base');
    const contentRef = useRef<HTMLDivElement>(null);

    // Voice related state
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    const generateQuickSet = async () => {
        stopSpeaking();
        setIsGenerating(true);
        setContent('');
        setTitle(`PL-300 Integrated Practice Exam`);
        try {
            await generatePracticeExamStream((chunk) => {
                setContent(prev => prev + chunk);
            }, selectedCount);
        } catch (err) {
            console.error(err);
            setContent("## Error\nAn error occurred during generation. Please try again.");
        } finally {
            setIsGenerating(false);
        }
    };

    const stopSpeaking = () => {
        if (audioSourceRef.current) {
            try { audioSourceRef.current.stop(); } catch (e) {}
            audioSourceRef.current = null;
        }
        setIsSpeaking(false);
        setIsGeneratingAudio(false);
    };

    const handleReadAloud = async () => {
        if (isSpeaking || isGeneratingAudio) {
            stopSpeaking();
            return;
        }

        if (!content) return;

        setIsGeneratingAudio(true);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }

            const cleanText = content.substring(0, 5000).replace(/\[ANSWER_(START|END)\]/g, '');
            const buffer = await generateSpeech(cleanText, 'Zephyr', audioContextRef.current);
            setIsGeneratingAudio(false);

            if (!audioContextRef.current) return;
            setIsSpeaking(true);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => setIsSpeaking(false);
            audioSourceRef.current = source;
            source.start();
        } catch (err) {
            console.error("Speech generation failed", err);
            setIsGeneratingAudio(false);
            setIsSpeaking(false);
        }
    };

    const handlePrint = () => {
        if (!content) return;
        window.print();
    };

    const getFontSizeClass = () => {
        switch (fontSize) {
            case 'sm': return 'text-sm';
            case 'lg': return 'text-lg';
            case 'xl': return 'text-xl';
            default: return 'text-base';
        }
    };

    // Robustly handle interspersed content
    const processedContent = useMemo(() => {
        if (includeAnswers) {
            return content.replace(/\[ANSWER_(START|END)\]/g, '');
        }
        return content.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answer hidden)*\n');
    }, [content, includeAnswers]);

    const printableContent = useMemo(() => {
        let text = content;
        if (!includeAnswers) {
            text = text.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answers omitted)*\n');
        } else {
            text = text.replace(/\[ANSWER_START\]/g, '\n<div class="answer-block">')
                       .replace(/\[ANSWER_END\]/g, '</div>\n');
        }
        return text;
    }, [content, includeAnswers]);

    return (
        <div className="space-y-8 animate-fade-in max-w-5xl mx-auto pb-20">
            {/* Control Panel - Hidden during print */}
            <div className="bg-card p-6 rounded-2xl shadow-xl border border-border flex flex-col gap-6 print:hidden">
                <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                    <div className="flex items-center gap-4">
                        <button 
                            onClick={onBackToDashboard}
                            className="p-2.5 hover:bg-border rounded-xl transition-all border border-transparent hover:border-border"
                            title="Back to Dashboard"
                        >
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                        </button>
                        <div>
                            <h2 className="text-2xl font-bold tracking-tight">Study Hub</h2>
                            <p className="text-sm text-slate-400">Integrated Q&A for focused learning</p>
                        </div>
                    </div>

                    <div className="flex flex-wrap items-center gap-4">
                        {content && (
                            <button
                                onClick={handleReadAloud}
                                className={`flex items-center gap-2 font-bold py-3 px-6 rounded-xl shadow-lg transition-all ${
                                    isSpeaking || isGeneratingAudio ? 'bg-danger text-white scale-105' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
                                }`}
                            >
                                {isSpeaking || isGeneratingAudio ? <StopIcon className="w-5 h-5" /> : <SpeakerIcon className="w-5 h-5" />}
                                {isGeneratingAudio ? 'Synthesizing...' : isSpeaking ? 'Stop Reading' : 'Listen'}
                            </button>
                        )}
                        <button
                            onClick={generateQuickSet}
                            disabled={isGenerating}
                            className="bg-primary hover:bg-primary/90 text-white font-bold py-3 px-8 rounded-xl shadow-lg shadow-primary/20 flex items-center gap-2 transition-all disabled:opacity-50 hover:-translate-y-0.5"
                        >
                            <SparklesIcon className="w-5 h-5" />
                            {isGenerating ? 'Generating...' : content ? 'Re-Generate' : 'Generate Exam Set'}
                        </button>

                        {content && !isGenerating && (
                            <button
                                onClick={handlePrint}
                                className="bg-success hover:bg-success/90 text-white font-extrabold py-3 px-8 rounded-xl flex items-center gap-2 transition-all hover:-translate-y-0.5 shadow-lg shadow-success/20"
                            >
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                                Print / Save PDF
                            </button>
                        )}
                    </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 pt-6 border-t border-border/50">
                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Total Questions</label>
                        <select 
                            value={selectedCount}
                            onChange={(e) => setSelectedCount(Number(e.target.value) as QuestionCount)}
                            className="w-full bg-background border border-border rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-primary focus:outline-none transition-all"
                            disabled={isGenerating}
