                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Answer Display</label>
                        <div className="flex items-center gap-4 bg-background border border-border rounded-lg px-4 py-2.5">
                            <label className="flex items-center gap-2 text-sm cursor-pointer select-none">
                                <input 
                                    type="checkbox" 
                                    checked={includeAnswers} 
                                    onChange={(e) => setIncludeAnswers(e.target.checked)}
                                    className="w-4 h-4 rounded text-primary focus:ring-primary border-slate-700 bg-slate-800"
                                />
                                Show Answers integrated
                            </label>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Text Size</label>
                        <div className="flex items-center gap-2">
                            {(['sm', 'base', 'lg', 'xl'] as FontSize[]).map(size => (
                                <button
                                    key={size}
                                    onClick={() => setFontSize(size)}
                                    className={`flex-1 py-2 px-1 text-xs font-bold rounded-lg border transition-all ${fontSize === size ? 'bg-primary border-primary text-white' : 'bg-background border-border text-slate-500 hover:border-slate-500'}`}
                                >
