                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Preview Container */}
            {!content && !isGenerating ? (
                <div className="bg-card/30 border-2 border-dashed border-border rounded-[2rem] p-20 text-center animate-fade-in print:hidden">
                    <h3 className="text-3xl font-extrabold mb-4">Ready to Study Integrated?</h3>
                    <p className="text-slate-400 max-w-lg mx-auto mb-10 text-lg leading-relaxed">
                        In this mode, each question is followed immediately by its answer. Great for learning as you go or listening to the full session with AI voice.
