import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Question, Difficulty, QuestionCategory, StudyGuideLength, QuestionType } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY! });

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const questionSchema = {
  type: Type.OBJECT,
  properties: {
    type: { 
        type: Type.STRING, 
        enum: ['MultipleChoice', 'MultiSelect', 'BuildList', 'Matching', 'CaseStudy']
    },
    question: { type: Type.STRING },
    context: { type: Type.STRING, description: 'Optional: Detailed scenario for CaseStudy types.' },
    options: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: 'List of options. For matching, options contain both sets.'
    },
    answer: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: 'For MultipleChoice, a single string in an array. For MultiSelect, multiple strings. For BuildList, the strings in the correct order. For Matching, pairs like "Item:Target".'
    },
    explanation: { type: Type.STRING },
    category: {
      type: Type.STRING,
      enum: ['Prepare the data', 'Model the data', 'Visualize and analyze the data', 'Deploy and maintain assets']
    },
    difficulty: {
      type: Type.STRING,
      enum: ['Easy', 'Medium', 'Hard']
    }
  },
  required: ['type', 'question', 'options', 'answer', 'explanation', 'category', 'difficulty']
};

export const generateQuestion = async (difficulty: Difficulty, category: QuestionCategory | 'All' = 'All'): Promise<Question> => {
    const model = 'gemini-3-pro-preview';
    const randomType = ['MultipleChoice', 'MultiSelect', 'BuildList', 'Matching', 'CaseStudy'][Math.floor(Math.random() * 5)];

    const prompt = `Generate a high-quality ${randomType} question for the Microsoft PL-300 Power BI exam.
    Category: ${category}
    Difficulty: ${difficulty === 'Adaptive' ? 'appropriate for level' : difficulty}

    REQUIREMENTS BY TYPE:
    - MultiSelect: User must choose 2 or 3 correct options.
    - BuildList: User must arrange actions in correct chronological/logical order.
    - Matching: User must match items from Column A to Column B.
    - CaseStudy: Provide a "context" field with a business scenario, followed by a specific question.
    - MultipleChoice: Single correct answer.

    Return the output in the specified JSON format. Ensure 'answer' is an array of strings.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: questionSchema,
                temperature: 0.9,
            },
        });

        const generated = JSON.parse(response.text);
        // Normalize answer format
        if (generated.type === 'MultipleChoice' && Array.isArray(generated.answer)) {
            generated.answer = generated.answer[0];
        }
        return generated as Question;
    } catch (error) {
        console.error("Error generating question:", error);
        throw new Error("Failed to generate question.");
    }
};

export const generateSpeech = async (text: string, voiceName: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    const ai = getAiClient();
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Read this exam question clearly: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("No audio data");

        return await decodeAudioData(decodeBase64(base64Audio), audioContext, 24000, 1);
    } catch (error) {
        console.error("Error generating speech:", error);
        throw error;
    }
};

export const getPersonalizedFeedback = async (question: Question, userAnswer: any): Promise<string> => {
    const model = 'gemini-3-flash-preview';
    const prompt = `Provide professional, encouraging feedback for a PL-300 student.
    Question: ${JSON.stringify(question)}
    User Answered: ${JSON.stringify(userAnswer)}
    Correct Answer is: ${JSON.stringify(question.answer)}

    Explain logically why they were right or wrong, focusing on Power BI best practices. Keep it under 100 words.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({ model, contents: prompt });
        return response.text;
    } catch (error) {
        return question.explanation;
    }
};

export const generatePracticeExamStream = async (onChunk: (chunk: string) => void, questionCount: number = 25): Promise<void> => {
    const model = 'gemini-3-pro-preview';
    const prompt = `Generate a unique PL-300 practice exam with exactly ${questionCount} questions.
    Mix types: Multiple Choice, Multi-Select, Drag-and-Drop (Matching), Build List (Reorder), and Case Studies.

    STRUCTURE FOR EACH QUESTION:
    1. **Question X [Type: {type}] [Domain: {category}]**
    2. Scenario/Context (if applicable)
    3. The Question Text
    4. Options/Items
    5. [ANSWER_START]
       **Correct Answer:** {detailed correct answer representation}
       **Explanation:** {why it is correct}
       [ANSWER_END]

    Separate each question with a horizontal rule. Formatting should be professional and suitable for printing.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContentStream({
            model,
            contents: prompt,
            config: { temperature: 1.0 },
        });

        for await (const chunk of response) {
            if (chunk.text) onChunk(chunk.text);
        }
    } catch (error) {
        console.error("Exam generation failed", error);
        throw error;
    }
};

