interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;
const AVAILABLE_VOICES = ['Zephyr', 'Puck', 'Charon', 'Kore', 'Fenrir'];

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | string[] | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  // Speech states
  const [selectedVoice, setSelectedVoice] = useState('Zephyr');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
        try { audioSourceRef.current.stop(); } catch (e) {}
        audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  useEffect(() => {
    if (timer === 0) return;
    if (timeLeft <= 0) { finishQuiz(); return; }
    const intervalId = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  useEffect(() => {
    const loadInitialQuestion = async () => {
      setIsLoading(true);
      setError(null);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) { onQuizEnd([], 0); return; }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          const firstQuestion = await generateQuestion(difficulty, category);
          setQuestions([firstQuestion]);
          setIsLoading(false);
        } catch (err) {
          setError("Failed to generate question.");
          setIsLoading(false);
        }
      }
    };
    loadInitialQuestion();
  }, []);

  const handleReadAloud = async () => {
    if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
    if (!currentQuestion) return;
    setIsGeneratingAudio(true);
    try {
        if (!audioContextRef.current) audioContextRef.current = new AudioContext();
        const textToRead = `${currentQuestion.context || ''} ${currentQuestion.question}`;
        const buffer = await generateSpeech(textToRead, selectedVoice, audioContextRef.current);
        setIsGeneratingAudio(false);
        setIsSpeaking(true);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsSpeaking(false);
        audioSourceRef.current = source;
        source.start();
    } catch (err) {
        setIsGeneratingAudio(false);
        setIsSpeaking(false);
    }
  };

  const toggleMultiSelect = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr.filter(o => o !== option);
      return [...arr, option];
    });
  };

  const toggleBuildList = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr.filter(o => o !== option);
      return [...arr, option];
    });
  };

  const handleSubmit = () => {
    if (!selectedAnswer || quizState !== 'answering') return;
    let isCorrect = false;
    if (currentQuestion.type === 'MultipleChoice' || currentQuestion.type === 'CaseStudy') {
      isCorrect = selectedAnswer === currentQuestion.answer;
    } else {
      const userArr = Array.isArray(selectedAnswer) ? selectedAnswer : [selectedAnswer];
      const correctArr = Array.isArray(currentQuestion.answer) ? currentQuestion.answer : [currentQuestion.answer];

      if (currentQuestion.type === 'BuildList') {
        isCorrect = JSON.stringify(userArr) === JSON.stringify(correctArr);
      } else {
        isCorrect = userArr.length === correctArr.length && userArr.every(v => correctArr.includes(v));
      }
    }

    setResults(prev => [...prev, { question: currentQuestion, userAnswer: selectedAnswer, isCorrect }]);
    setQuizState('answered');
  };

  const handleNextQuestion = async () => {
    stopSpeaking();
    const totalInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
    if (currentQuestionIndex + 1 >= totalInSet) { finishQuiz(); return; }

    setIsLoading(true);
    try {
      const nextQ = await generateQuestion(difficulty, category);
      setQuestions(prev => [...prev, nextQ]);
      setCurrentQuestionIndex(prev => prev + 1);
      setSelectedAnswer(null);
      setQuizState('answering');
    } catch (err) {
      setError("Failed to load next question.");
    } finally {
      setIsLoading(false);
    }
  };

  const renderOptions = () => {
    const { type, options } = currentQuestion;

    switch (type) {
      case 'MultiSelect':
        return (
          <div className="space-y-3">
            <p className="text-sm text-primary-light font-bold mb-2 uppercase tracking-tight">Select all that apply:</p>
            {options.map((opt, i) => {
              const isSelected = Array.isArray(selectedAnswer) && selectedAnswer.includes(opt);
              return (
                <button key={i} onClick={() => toggleMultiSelect(opt)} disabled={quizState === 'answered'} className={`w-full text-left p-4 rounded-xl border-2 flex items-center gap-4 transition-all ${isSelected ? 'border-primary bg-primary/10' : 'border-border bg-card'}`}>
                  <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${isSelected ? 'bg-primary border-primary' : 'border-slate-600'}`}>
                    {isSelected && <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>}
                  </div>
                  <span>{opt}</span>
                </button>
              );
            })}
          </div>
        );
      case 'BuildList':
        return (
          <div className="space-y-4">
             <p className="text-sm text-primary-light font-bold mb-2 uppercase tracking-tight">Select in correct sequence:</p>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-500 uppercase">Available Steps</h4>
                    {options.filter(o => !(Array.isArray(selectedAnswer) && selectedAnswer.includes(o))).map((opt, i) => (
                        <button key={i} onClick={() => toggleBuildList(opt)} disabled={quizState === 'answered'} className="w-full text-left p-3 bg-slate-800 border border-border rounded-lg text-sm hover:border-primary transition-all">
                            {opt}
                        </button>
                    ))}
                </div>
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-500 uppercase">Your Sequence</h4>
                    {Array.isArray(selectedAnswer) && selectedAnswer.map((opt, i) => (
                        <button key={i} onClick={() => toggleBuildList(opt)} disabled={quizState === 'answered'} className="w-full text-left p-3 bg-primary/20 border border-primary rounded-lg text-sm flex items-center gap-3">
                            <span className="font-bold text-primary">{i+1}</span>
                            <span>{opt}</span>
                        </button>
                    ))}
                    {(!selectedAnswer || selectedAnswer.length === 0) && <div className="p-8 border-2 border-dashed border-border rounded-lg text-center text-slate-500 text-xs italic">Select steps from the left</div>}
                </div>
             </div>
          </div>
        );
      case 'Matching':
         return <div className="p-4 bg-slate-900 rounded-lg text-sm text-slate-400 italic">Matching type: Select pairs conceptually in your mind and provide the best match list below. (AI will evaluate your freeform or selection mapping).</div>;
      default:
        return (
          <div className="space-y-3">
            {options.map((opt, i) => (
              <button key={i} onClick={() => setSelectedAnswer(opt)} disabled={quizState === 'answered'} className={`w-full text-left p-4 rounded-xl border-2 flex items-center gap-4 transition-all ${selectedAnswer === opt ? 'border-primary bg-primary/10' : 'border-border bg-card'}`}>
                 <div className={`w-5 h-5 rounded-full border-2 ${selectedAnswer === opt ? 'border-primary bg-primary ring-2 ring-primary/20' : 'border-slate-600'}`} />
                 <span>{opt}</span>
              </button>
            ))}
          </div>
        );
    }
  };

  if (isLoading && questions.length === 0) return <Loader text="Assembling dynamic exam content..." />;

  return (
    <div className="max-w-4xl mx-auto animate-fade-in pb-20 px-4 sm:px-0">
        <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black tracking-tight flex items-center gap-3 text-slate-100">
                <span className="text-primary">PL-300</span> {mode}
            </h2>
            {timer > 0 && (
                <div className="flex items-center gap-3 font-mono font-bold px-4 py-2 rounded-full border border-border bg-card shadow-lg">
                    <StopwatchIcon className="w-5 h-5 text-primary" />
                    <span className="text-xl text-slate-200">{Math.floor(timeLeft/60)}:{(timeLeft%60).toString().padStart(2, '0')}</span>
                </div>
            )}
        </div>

        {currentQuestion.context && (
            <div className="mb-8 p-6 bg-slate-800/50 rounded-2xl border-l-4 border-primary shadow-xl animate-fade-in-up">
                <h4 className="text-xs font-black uppercase text-primary tracking-widest mb-3">Case Study Scenario</h4>
                <div className="text-slate-300 text-sm leading-relaxed prose prose-invert max-w-none">
                    {currentQuestion.context}
                </div>
            </div>
        )}

        <div className="bg-card p-8 sm:p-12 rounded-3xl shadow-2xl border border-border relative overflow-hidden">
            <div className="flex justify-between items-start mb-10">
                <div>
                   <span className="inline-block bg-primary/20 text-primary-light text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest mb-4 border border-primary/20">
                     {currentQuestion.type} • Question {currentQuestionIndex + 1}
                   </span>
                   <h3 className="text-xl md:text-2xl font-bold leading-tight text-slate-100">{currentQuestion.question}</h3>
                </div>
                <div className="flex gap-2">
                    <button onClick={handleReadAloud} className={`p-2 rounded-xl transition-all ${isSpeaking || isGeneratingAudio ? 'bg-danger text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}>
                        {isSpeaking || isGeneratingAudio ? <StopIcon className="w-5 h-5" /> : <SpeakerIcon className="w-5 h-5" />}
                    </button>
                    <button onClick={() => onToggleBookmark(currentQuestion)} className={`p-2 rounded-xl transition-all ${isBookmarked(currentQuestion) ? 'text-yellow-400 bg-yellow-400/10' : 'text-slate-500 hover:text-yellow-400'}`}>
                        <BookmarkIcon filled={isBookmarked(currentQuestion)} />
                    </button>
                </div>
            </div>

            {renderOptions()}

            {quizState === 'answered' && (
                <div className="mt-10 pt-10 border-t border-border animate-fade-in-up">
                    <DexterExplains question={currentQuestion} userAnswer={results[results.length-1].userAnswer} />
                </div>
            )}

            <div className="mt-12 flex flex-col sm:flex-row gap-4">
                {quizState === 'answering' ? (
                    <button onClick={handleSubmit} disabled={!selectedAnswer || (Array.isArray(selectedAnswer) && selectedAnswer.length === 0)} className="flex-1 bg-primary hover:bg-primary/90 text-white font-black py-4 px-8 rounded-2xl text-lg shadow-xl shadow-primary/20 transition-all disabled:opacity-50">
                        Submit Answer
                    </button>
                ) : (
                    <button onClick={handleNextQuestion} className="flex-1 bg-primary hover:bg-primary/90 text-white font-black py-4 px-8 rounded-2xl text-lg shadow-xl shadow-primary/20 transition-all flex items-center justify-center gap-3">
                        {currentQuestionIndex + 1 === (mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS) ? 'Complete Session' : 'Next Question'}
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                    </button>
                )}
            </div>
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

import React from 'react';
import type { Question } from '../types';
import { DexterExplains } from './DexterExplains';
import { CheckIcon } from './icons/CheckIcon';
import { XIcon } from './icons/XIcon';

interface QuestionDetailProps {
    question: Question;
    userAnswer?: string | string[] | null;
}

export const QuestionDetail: React.FC<QuestionDetailProps> = ({ question, userAnswer }) => {

    const isOptionSelected = (opt: string) => {
        if (!userAnswer) return false;
        return Array.isArray(userAnswer) ? userAnswer.includes(opt) : userAnswer === opt;
    };

    const isOptionCorrect = (opt: string) => {
        return Array.isArray(question.answer) ? question.answer.includes(opt) : question.answer === opt;
    };

    const getOptionClass = (opt: string) => {
        const correct = isOptionCorrect(opt);
        const selected = isOptionSelected(opt);

        if (correct) return 'bg-success/20 border-success text-success';
        if (selected && !correct) return 'bg-danger/20 border-danger text-danger';
        return 'bg-card opacity-50 border-border';
    };

    return (
        <div className="bg-card/50 p-6 md:p-10 my-4 rounded-3xl border border-border animate-fade-in shadow-xl">
            <span className="text-[10px] font-black bg-primary/20 text-primary-light px-2 py-1 rounded-md uppercase tracking-widest mb-4 inline-block">
                Reviewing {question.type}
            </span>

            {question.context && (
                <div className="mb-6 p-4 bg-slate-800/30 rounded-xl text-xs text-slate-400 italic">
                    {question.context}
                </div>
            )}

            <h3 className="text-lg font-bold mb-6 text-slate-100">{question.question}</h3>

            <div className="space-y-3 mb-8">
                {question.options.map((option, index) => (
                    <div key={index} className={`p-4 rounded-xl border-2 flex items-center justify-between transition-all ${getOptionClass(option)}`}>
                        <span className="text-sm font-medium">{option}</span>
                        <div className="flex gap-2">
                             {isOptionCorrect(option) && <CheckIcon />}
                             {isOptionSelected(option) && !isOptionCorrect(option) && <XIcon />}
                        </div>
                    </div>
                ))}
            </div>

            {question.type === 'BuildList' && Array.isArray(question.answer) && (
                <div className="mb-8 p-4 bg-primary/10 border border-primary/20 rounded-xl">
                    <h4 className="text-xs font-bold text-primary uppercase tracking-widest mb-3">Correct Ordering:</h4>
                    <div className="space-y-2">
                        {question.answer.map((ans, i) => (
                            <div key={i} className="flex items-center gap-3 text-sm text-slate-200">
                                <span className="w-6 h-6 flex items-center justify-center bg-primary text-white rounded-full font-bold text-xs">{i+1}</span>
                                <span>{ans}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="mt-8">
                 <DexterExplains question={question} userAnswer={userAnswer} />
            </div>
        </div>
    );
};

import React, { useState, useRef, useMemo } from 'react';
import { generatePracticeExamStream, generateSpeech } from '../services/geminiService';
import { DocumentDownloadIcon } from './icons/DocumentDownloadIcon';
import { XIcon } from './icons/XIcon';
import { SparklesIcon } from './icons/SparklesIcon';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';

declare const saveAs: (blob: Blob, filename: string) => void;

interface PracticeExamDownloaderProps {
    onClose: () => void;
}

export const PracticeExamDownloader: React.FC<PracticeExamDownloaderProps> = ({ onClose }) => {
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState('');
    const [examContent, setExamContent] = useState('');
    const [includeAnswers, setIncludeAnswers] = useState(true);
    const examContentRef = useRef('');

    const [isSpeaking, setIsSpeaking] = useState(false);
    const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    const handleGenerate = async () => {
        stopSpeaking();
        setIsGenerating(true);
        setError('');
        setExamContent('');
        examContentRef.current = '';

        try {
            await generatePracticeExamStream((chunk) => {
                examContentRef.current += chunk;
                setExamContent(examContentRef.current);
            });
        } catch (err) {
            setError("Generation encountered an error.");
        } finally {
            setIsGenerating(false);
        }
    };

    const stopSpeaking = () => {
        if (audioSourceRef.current) {
            try { audioSourceRef.current.stop(); } catch (e) {}
            audioSourceRef.current = null;
        }
        setIsSpeaking(false);
        setIsGeneratingAudio(false);
    };

    const handleReadAloud = async () => {
        if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
        if (!examContent) return;
        setIsGeneratingAudio(true);
        try {
            if (!audioContextRef.current) audioContextRef.current = new AudioContext();
            const textToRead = examContent.substring(0, 4000).replace(/\[ANSWER_(START|END)\]/g, '');
            const buffer = await generateSpeech(textToRead, 'Zephyr', audioContextRef.current);
            setIsGeneratingAudio(false);
            setIsSpeaking(true);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => setIsSpeaking(false);
            audioSourceRef.current = source;
            source.start();
        } catch (err) {
            setIsGeneratingAudio(false);
            setIsSpeaking(false);
        }
    };

    const processedContent = useMemo(() => {
        let text = examContent;
        if (!includeAnswers) {
            text = text.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answers are hidden for testing)*\n');
        } else {
            text = text.replace(/\[ANSWER_START\]/g, '\n<div class="answer-box">')
                       .replace(/\[ANSWER_END\]/g, '</div>\n');
        }
        return text;
    }, [examContent, includeAnswers]);

    return (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 p-4 print:p-0 print:bg-white print:static" role="dialog">
            <div className="bg-card rounded-[2.5rem] shadow-2xl w-full max-w-4xl h-[85vh] overflow-hidden flex flex-col animate-pop-in print:hidden">
                <div className="p-8 border-b border-border flex justify-between items-center">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-primary/10 rounded-2xl">
                           <DocumentDownloadIcon className="text-primary w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black tracking-tight">Full Exam Generator</h2>
                            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Questions & Answers Interspersed</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-white text-4xl font-light">&times;</button>
                </div>

                <div className="flex-1 overflow-y-auto p-10 space-y-8 custom-scrollbar bg-background/20">
                    {!examContent && !isGenerating ? (
                        <div className="py-24 text-center">
                            <SparklesIcon className="w-16 h-16 text-primary/40 mx-auto mb-8 animate-pulse" />
                            <h3 className="text-3xl font-black mb-4">Master Every Item Type</h3>
                            <p className="text-slate-400 max-w-md mx-auto mb-10 text-lg leading-relaxed">
                                Our AI will construct a unique exam including <b>Case Studies</b>, <b>Build Lists</b>, <b>Matching</b>, and <b>Multi-Select</b> items.
                            </p>
                            <button onClick={handleGenerate} className="bg-primary hover:bg-primary/90 text-white font-black py-5 px-14 rounded-2xl shadow-2xl shadow-primary/30 transition-all active:scale-95 text-xl">
                                Generate Professional Exam
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-8">
                            <div className="sticky top-0 z-10 flex flex-wrap items-center justify-between gap-6 p-4 bg-card/90 backdrop-blur-xl border border-border rounded-2xl shadow-xl">
                                <label className="flex items-center gap-3 text-sm font-black cursor-pointer uppercase tracking-tighter">
                                    <input type="checkbox" checked={includeAnswers} onChange={e => setIncludeAnswers(e.target.checked)} className="w-5 h-5 rounded-lg text-primary bg-slate-800 border-border" />
                                    Show Answers Below Questions
                                </label>
                                <div className="flex gap-3">
                                    <button onClick={handleReadAloud} className={`px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all ${isSpeaking || isGeneratingAudio ? 'bg-danger text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}>
                                        {isSpeaking || isGeneratingAudio ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                                        {isSpeaking ? 'Stop Reading' : 'Listen'}
                                    </button>
                                    <button onClick={() => window.print()} className="bg-success text-white px-6 py-3 rounded-xl font-black hover:bg-success/90 transition-all shadow-lg shadow-success/20">
                                        Download PDF
                                    </button>
                                </div>
                            </div>

                            <div className="prose prose-invert max-w-none font-serif text-slate-300 leading-relaxed whitespace-pre-wrap">
                                {isGenerating && !examContent ? <Loader text="Drafting complex scenarios and build lists..." /> : processedContent}
                            </div>

                            {isGenerating && (
                                <div className="flex items-center gap-4 text-primary font-black animate-pulse bg-primary/5 p-6 rounded-2xl border border-primary/20">
                                    <svg className="animate-spin h-6 w-6" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg>
                                    Streaming remaining items...
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="p-6 bg-card border-t border-border flex justify-center">
                    <button onClick={onClose} className="text-slate-500 hover:text-slate-300 font-black text-sm uppercase tracking-widest transition-colors">Close Generator</button>
                </div>
            </div>

            <div className="hidden print:block print:bg-white print:text-black w-full print:p-8">
                <div style={{ textAlign: 'center', marginBottom: '2cm', borderBottom: '2px solid black', paddingBottom: '1cm' }}>
                    <h1 style={{ fontSize: '24pt', fontWeight: '900', textTransform: 'uppercase', marginBottom: '0.2cm' }}>PL-300: Power BI Practice Exam</h1>
                    <p style={{ fontSize: '10pt', fontWeight: 'bold', color: '#666' }}>Mixed Item Type Assessment • Interleaved Solutions</p>
                </div>
                <div style={{ fontFamily: 'serif', whiteSpace: 'pre-wrap', lineHeight: '1.6', fontSize: '11pt' }}>
                    <div dangerouslySetInnerHTML={{ __html: processedContent }} />
                </div>
            </div>

            <style dangerouslySetInnerHTML={{ __html: `
                .answer-box {
                    background: #f9fafb !important;
                    border-left: 5px solid black !important;
                    padding: 1.5rem !important;
                    margin: 1rem 0 2.5rem 0 !important;
                    font-style: normal !important;
                    color: #111 !important;
                    break-inside: avoid !important;
                }
                @media print {
                    @page { margin: 2cm; size: A4 portrait; }
                    html, body { background: white !important; color: black !important; }
                    .print\\:hidden { display: none !important; }
                }
            `}} />
        </div>
    );
};

